import { differenceInCalendarDays, parseISO } from 'date-fns'
import type { FertilityKey } from './messages'

/**
 * The four later fertility features (FE13–FE16), same house rules as
 * `fertilityMath.ts`: arithmetic on values the owner typed, message keys instead
 * of copy, no diagnosis, no norm, no verdict. Nothing here decides whether a
 * reading is healthy — a weight or a blood pressure comes back as the *range* of
 * what was logged, never as "normal" or "tinggi".
 */

// ---------------------------------------------------------------------------
// FE13 — weight & blood-pressure logs, shown as ranges
// ---------------------------------------------------------------------------

export type VitalField = 'weightKg' | 'sistol' | 'diastol'
export const VITAL_FIELDS: readonly VitalField[] = ['weightKg', 'sistol', 'diastol']

export interface VitalLog {
  date: string
  weightKg?: number
  sistol?: number
  diastol?: number
}

/**
 * Deliberately absurd outer bounds — the same trick `pregnancyPlan.ts` uses for
 * ANC measures. These are **not** normal ranges and must never be narrowed into
 * any: a value outside them is a typo (a weight in grams, a decimal point in the
 * wrong place), and the copy says exactly that. Whether a real reading is fine
 * is a bidan's call, not this file's.
 */
const VITAL_BOUNDS: Record<VitalField, [number, number]> = {
  weightKg: [20, 250],
  sistol: [40, 300],
  diastol: [20, 200],
}

export interface VitalRange {
  min: number
  max: number
  /** Oldest and newest logged value, so the card can show movement as a span. */
  first: number
  last: number
  count: number
}

export interface VitalsSummary {
  weight: VitalRange | null
  sistol: VitalRange | null
  diastol: VitalRange | null
  typos: VitalField[]
  messageKey: FertilityKey
}

function rangeOf(logs: VitalLog[], field: VitalField): VitalRange | null {
  const points = logs
    .filter((l) => typeof l[field] === 'number' && Number.isFinite(l[field]))
    .map((l) => ({ date: l.date, value: l[field] as number }))
    .sort((a, b) => a.date.localeCompare(b.date))
  if (points.length === 0) return null
  const values = points.map((p) => p.value)
  return {
    min: Math.min(...values),
    max: Math.max(...values),
    first: points[0]!.value,
    last: points.at(-1)!.value,
    count: values.length,
  }
}

/**
 * A range per field, and the fields whose value can't be a real reading at all.
 * A range is presented as a range on purpose: a single "your BP is 120/80" reads
 * as a verdict, and this module has no opinion on whether any reading is fine.
 */
export function vitalsSummary(logs: VitalLog[]): VitalsSummary {
  const typos = VITAL_FIELDS.filter((f) =>
    logs.some(
      (l) =>
        typeof l[f] === 'number' &&
        Number.isFinite(l[f]) &&
        ((l[f] as number) < VITAL_BOUNDS[f][0] || (l[f] as number) > VITAL_BOUNDS[f][1]),
    ),
  )
  const weight = rangeOf(logs, 'weightKg')
  const sistol = rangeOf(logs, 'sistol')
  const diastol = rangeOf(logs, 'diastol')
  const any = weight || sistol || diastol

  return {
    weight,
    sistol,
    diastol,
    typos,
    messageKey: typos.length
      ? 'fertility.vital.typo'
      : any
        ? 'fertility.vital.sum.some'
        : 'fertility.vital.sum.none',
  }
}

// ---------------------------------------------------------------------------
// FE14 — IVF / IUI cycle: phases, appointments, a gentle wait
// ---------------------------------------------------------------------------

export const ART_METHODS = ['ivf', 'iui'] as const
export type ArtMethod = (typeof ART_METHODS)[number]

/**
 * The protocol phases each route runs through, in order. These are the ordinary
 * stages a clinic talks a couple through — not a schedule and not a promise. The
 * clinic sets what actually happens and when; the app only lays the names out so
 * the owner can mark where they are. Every id resolves to `fertility.art.phase.<id>`.
 */
/** Every phase id used across both routes. Literal union → `fertility.art.phase.<id>` resolves. */
export const ART_PHASE_IDS = [
  'stimulasi',
  'pemantauan',
  'pemicuan',
  'pengambilan',
  'inseminasi',
  'transfer',
  'tunggu',
  'hasil',
] as const
export type ArtPhaseId = (typeof ART_PHASE_IDS)[number]

export const ART_PHASES: Record<ArtMethod, readonly ArtPhaseId[]> = {
  ivf: ['stimulasi', 'pemicuan', 'pengambilan', 'transfer', 'tunggu', 'hasil'],
  iui: ['pemantauan', 'pemicuan', 'inseminasi', 'tunggu', 'hasil'],
}

export type PhaseState = 'past' | 'now' | 'ahead'

export interface ArtPhaseStep {
  id: ArtPhaseId
  state: PhaseState
}

/**
 * The phases with one marked "now" — the one the owner set. Before they mark
 * anything, every phase is simply ahead; nothing is inferred from a date,
 * because a phase boundary is a clinic event, not a countdown.
 */
export function artPhaseTrack(method: ArtMethod, currentPhase?: string): ArtPhaseStep[] {
  const phases = ART_PHASES[method]
  const idx = currentPhase ? phases.indexOf(currentPhase as ArtPhaseId) : -1
  return phases.map((id, i) => ({
    id,
    state: idx < 0 ? 'ahead' : i < idx ? 'past' : i === idx ? 'now' : 'ahead',
  }))
}

export const ART_APPT_TYPES = ['konsultasi', 'usg', 'tindakan', 'beta', 'lainnya'] as const
export type ArtApptType = (typeof ART_APPT_TYPES)[number]

/**
 * The two-week wait — the part of IVF/IUI that this feature most has to get
 * right. It counts **up** from the procedure, never down to the beta test: a
 * ticking "3 days left" is exactly the pressure a couple in this window does not
 * need. The beta date, when the clinic has given one, is shown as a plain date
 * ("sekitar tanggal X"), not as a shrinking number.
 */
export interface ArtWait {
  /** Days since the procedure. Negative before it; day of is 0. */
  daysSince: number
  betaDate: string | null
  /** Days from today to the beta date — returned, but deliberately de-emphasised. */
  betaFromToday: number | null
  statusKey: FertilityKey
}

export function artWait(
  procedureDate: string,
  betaDate: string | undefined,
  today = new Date(),
): ArtWait {
  const daysSince = differenceInCalendarDays(today, parseISO(procedureDate))
  const betaFromToday =
    betaDate ? differenceInCalendarDays(parseISO(betaDate), today) : null

  const statusKey: FertilityKey =
    daysSince < 0
      ? 'fertility.art.wait.notYet'
      : betaFromToday !== null && betaFromToday <= 0
        ? 'fertility.art.wait.betaWindow'
        : 'fertility.art.wait.resting'

  return { daysSince, betaDate: betaDate ?? null, betaFromToday, statusKey }
}

// ---------------------------------------------------------------------------
// FE15 — IVF cost, kept in the finance domain
// ---------------------------------------------------------------------------

/**
 * Costs are not stored here — they are ordinary finance ledger rows, tagged with
 * this category, private by default (`C1_personal`), so the partner never sees
 * an amount unless the owner shares it in the finance screen. This module only
 * totals the rows the current viewer already owns; the read gate does the hiding.
 */
export const PROMIL_CATEGORY = 'promil'

export interface PromilCost {
  /** Signed like every ledger amount: negative is money out. */
  amount: number
  /** A bill/estimate not yet paid, vs. an actual outflow. */
  planned: boolean
}

export interface PromilSummary {
  plannedTotal: number
  actualTotal: number
  count: number
  messageKey: FertilityKey
}

/** Sums the owner's own promil rows. Amounts in are ignored; this counts spend. */
export function promilSummary(costs: PromilCost[]): PromilSummary {
  let plannedTotal = 0
  let actualTotal = 0
  for (const c of costs) {
    const out = Math.abs(Math.round(c.amount))
    if (c.planned) plannedTotal += out
    else actualTotal += out
  }
  return {
    plannedTotal,
    actualTotal,
    count: costs.length,
    messageKey: costs.length === 0 ? 'fertility.cost.sum.none' : 'fertility.cost.sum.some',
  }
}
