import { useState } from 'react'
import { Link } from 'react-router-dom'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field } from '@/components/ui'
import { useOwned } from '@/db/hooks'
import type { CycleLog } from '@/types/domain'
import { useI18n } from '@/i18n'
import { fmtDate } from '@/i18n/format'
import {
  ancSlotState,
  periodOutlook,
  postpartumProgress,
  postpartumSchedule,
  type AncState,
} from './fertilityMath'
import {
  MOOD_ITEMS,
  RECOVERY_SIGNS,
  moodReferral,
  recoveryReview,
  type MoodItemId,
  type MoodSurface,
  type RecoverySignId,
} from './postpartumCare'
import { Preconception, Questions } from './Trying'
import { savePpCheck, setBirthDate, toggleKf, type FertilityData, type Of } from './store'

/**
 * The panels for the four modes added by the state machine in `modes.ts`.
 *
 * `Trying` and `Pregnancy` already own the conception and pregnancy screens.
 * These are the quieter ones — and the point of them is what they leave out:
 * `NotTrying` renders no estimate at all, `Preventing` renders a period range
 * and explicitly refuses to be contraception, `Exploring` reuses the checklist
 * and question list with none of the tracking around them.
 */

export function NotTrying() {
  const { t } = useI18n()
  return (
    <Card title={t('fertility.tidak.title')} icon="private" hint={t('fertility.tidak.hint')}>
      <p>{t('fertility.tidak.body')}</p>
    </Card>
  )
}

/**
 * Preventing mode.
 *
 * Shows the next-period range and nothing else. There is no fertile window
 * here: an "unsafe days" band is the one number that would get read as
 * contraception, and this app does not get to be wrong about that.
 */
export function Preventing({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const cycles = useOwned<CycleLog>('cycles', me)
  const out = periodOutlook((cycles ?? []).map((c) => c.startDate))

  return (
    <Card title={t('fertility.cegah.title')} icon="cycle">
      {out.range === null ? (
        <EmptyState
          icon="cycle"
          title={t('fertility.outlook.none')}
          hint={t('fertility.outlook.noneHint')}
          action={
            <Link to="/siklus" className="btn btn--soft btn--sm">
              <Icon name="cycle" size={16} /> {t('fertility.outlook.openCycle')}
            </Link>
          }
        />
      ) : (
        <div className="stack stack--tight">
          <p>
            <strong>
              {t('fertility.outlook.range', {
                from: fmtDate(out.range[0], 'd MMM', locale),
                to: fmtDate(out.range[1], 'd MMM yyyy', locale),
              })}
            </strong>
          </p>
          <p className="card__hint">
            {t('fertility.outlook.based', {
              n: out.basedOnCycles,
              confidence: t(out.confidenceKey),
            })}
          </p>
          {out.averageLength !== null && (
            <p className="card__hint">
              {t('fertility.outlook.avg', {
                n: out.averageLength,
                variation: out.variationDays ?? 0,
              })}
            </p>
          )}
        </div>
      )}
      <p className="disclaimer">{t('fertility.cegah.caveat')}</p>
    </Card>
  )
}

export function Exploring({ me, data }: { me: string; data: FertilityData }) {
  const { t } = useI18n()
  return (
    <>
      <Card title={t('fertility.jelajah.title')} icon="info">
        <p>{t('fertility.jelajah.body')}</p>
      </Card>
      <Preconception me={me} checks={data.checks} />
      <Questions me={me} questions={data.questions} />
    </>
  )
}

/**
 * Postpartum mode.
 *
 * Counts days from a birth date the owner typed, and lays the four KF contact
 * windows against it. The day count is a fact, not an estimate, so it carries no
 * range — but the visit windows carry the same caveat the ANC schedule does: the
 * bidan or dokter sets the real dates, and no facility is named anywhere.
 */
export function Postpartum({ me, data }: { me: string; data: FertilityData }) {
  const { t, locale } = useI18n()
  const birth = data.births[0]
  const [draft, setDraft] = useState(birth?.date ?? format(new Date(), 'yyyy-MM-dd'))

  const slots = birth ? postpartumSchedule(birth.date) : []
  const progress = birth ? postpartumProgress(birth.date, data.kfVisits.map((v) => v.slotId)) : null

  const stateKey = (s: AncState) => `fertility.pp.state.${s}` as const

  return (
    <>
      <Card title={t('fertility.pp.title')} icon="baby">
        <div className="stack stack--tight">
          <Field label={t('fertility.pp.birth')} hint={t('fertility.pp.birthHint')}>
            {(p) => (
              <input
                {...p}
                type="date"
                value={draft}
                onChange={(e) => {
                  setDraft(e.target.value)
                  if (e.target.value) setBirthDate(me, birth, e.target.value)
                }}
              />
            )}
          </Field>

          {progress === null ? (
            <EmptyState
              icon="baby"
              title={t('fertility.pp.none')}
              hint={t('fertility.pp.noneHint')}
            />
          ) : progress.day < 0 ? (
            <p>{t('fertility.pp.beforeBirth', { n: -progress.day })}</p>
          ) : (
            <>
              <p>
                <strong>{t('fertility.pp.day', { n: progress.day })}</strong>
              </p>
              {!progress.withinWindow && <p className="card__hint">{t('fertility.pp.after')}</p>}
              <p className="card__hint">
                {t(progress.messageKey, { n: progress.doneCount, total: progress.total })}
              </p>
            </>
          )}
          <p className="disclaimer">{t('fertility.pp.caveat')}</p>
        </div>
      </Card>

      {birth && (
        <Card title={t('fertility.pp.kf')} icon="calendar" hint={t('fertility.pp.kfHint')}>
          <ul className="list">
            {slots.map((s) => {
              const logged = data.kfVisits.find((v) => v.slotId === s.id)
              const state = ancSlotState(s, !!logged)
              return (
                <li key={s.id} className="list__item">
                  <input
                    type="checkbox"
                    checked={!!logged}
                    aria-label={t('fertility.pp.kf.logged')}
                    onChange={() => toggleKf(me, logged, s.id, s.fromDate)}
                  />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{t(`fertility.pp.kf.${s.id}`)}</strong>
                    <span className="card__hint">
                      {fmtDate(s.fromDate, 'd MMM', locale)} – {fmtDate(s.toDate, 'd MMM yyyy', locale)}
                      {' · '}
                      {t(stateKey(state))}
                    </span>
                  </span>
                </li>
              )
            })}
          </ul>
        </Card>
      )}

      <PostpartumCheckIn me={me} data={data} />
    </>
  )
}

/**
 * FE17 — the daily postpartum check-in.
 *
 * Two checklists, one date. Physical recovery signs and a mood check-in, each
 * ticked straight onto today's record. Neither produces a number: `recoveryReview`
 * says only whether something is worth contacting a bidan/dokter about, and
 * `moodReferral` produces a *referral surface* — nothing, "worth telling someone",
 * or "reach out now" when a self-harm thought is ticked — never a score. The
 * urgent surface names no clinic and no hotline number, because inventing one is
 * exactly the referral-without-a-source the blueprint forbids.
 */
function PostpartumCheckIn({ me, data }: { me: string; data: FertilityData }) {
  const { t, locale } = useI18n()
  const date = format(new Date(), 'yyyy-MM-dd')
  const todayRow: Of<'fert_ppcheck'> | undefined = data.ppChecks.find((c) => c.date === date)
  const recovery = todayRow?.recovery ?? []
  const mood = todayRow?.mood ?? []

  const review = recoveryReview(recovery)
  const referral = moodReferral(mood)

  const surfaceIcon: Record<MoodSurface, 'heart' | 'referral' | 'emergency'> = {
    none: 'heart',
    gentle: 'referral',
    urgent: 'emergency',
  }

  function toggleRecovery(id: RecoverySignId) {
    const next = recovery.includes(id) ? recovery.filter((x) => x !== id) : [...recovery, id]
    savePpCheck(me, todayRow, { date, recovery: next, mood, note: todayRow?.note })
  }
  function toggleMood(id: MoodItemId) {
    const next = mood.includes(id) ? mood.filter((x) => x !== id) : [...mood, id]
    savePpCheck(me, todayRow, { date, recovery, mood: next, note: todayRow?.note })
  }

  return (
    <>
      <Card title={t('fertility.pp.recovery.title')} icon="health" hint={t('fertility.pp.recovery.hint')}>
        <div className="stack stack--tight">
          <fieldset style={{ border: 0, padding: 0, margin: 0 }}>
            <legend className="visually-hidden">{t('fertility.pp.recovery.title')}</legend>
            <div className="fert-signs">
              {RECOVERY_SIGNS.map((s) => (
                <label key={s.id}>
                  <input
                    type="checkbox"
                    checked={recovery.includes(s.id)}
                    onChange={() => toggleRecovery(s.id)}
                  />
                  <span>{t(`fertility.pp.recovery.sign.${s.id}`)}</span>
                </label>
              ))}
            </div>
          </fieldset>

          {review.seekCare ? (
            <div className="fert-level fert-level--merah" role="status">
              <Icon name="emergency" size={20} />
              <span className="stack stack--tight">
                <strong>{t('fertility.pp.recovery.seek')}</strong>
                <span>{review.flagged.map((f) => t(`fertility.pp.recovery.sign.${f}`)).join(' · ')}</span>
              </span>
            </div>
          ) : (
            <p className="card__hint">{t(review.messageKey)}</p>
          )}
        </div>
      </Card>

      <Card title={t('fertility.pp.mood.title')} icon="heart" hint={t('fertility.pp.mood.hint')}>
        <div className="stack stack--tight">
          <fieldset style={{ border: 0, padding: 0, margin: 0 }}>
            <legend className="visually-hidden">{t('fertility.pp.mood.title')}</legend>
            <div className="fert-signs">
              {MOOD_ITEMS.map((m) => (
                <label key={m.id}>
                  <input type="checkbox" checked={mood.includes(m.id)} onChange={() => toggleMood(m.id)} />
                  <span>{t(`fertility.pp.mood.item.${m.id}`)}</span>
                </label>
              ))}
            </div>
          </fieldset>

          {/* A referral surface, never a score. */}
          {referral.surface === 'none' ? (
            <p className="card__hint">{t(referral.messageKey)}</p>
          ) : (
            <div
              className={`fert-level fert-level--${referral.surface === 'urgent' ? 'merah' : 'kuning'}`}
              role="status"
            >
              <Icon name={surfaceIcon[referral.surface]} size={20} />
              <span className="stack stack--tight">
                <strong>{t(referral.messageKey)}</strong>
                <span>{t(referral.actionKey)}</span>
              </span>
            </div>
          )}

          <Field label={t('fertility.pp.check.note')} hint={t('fertility.pp.check.noteHint')}>
            {(p) => (
              <textarea
                {...p}
                defaultValue={todayRow?.note ?? ''}
                onBlur={(e) =>
                  savePpCheck(me, todayRow, { date, recovery, mood, note: e.target.value || undefined })
                }
              />
            )}
          </Field>

          <p className="card__hint">{t('fertility.pp.check.private')}</p>
          <p className="disclaimer">{t('fertility.pp.mood.disclaimer')}</p>
        </div>
      </Card>

      {data.ppChecks[0] && (
        <p className="card__hint">
          {t('fertility.pp.check.history', {
            date: fmtDate(data.ppChecks[0].date, 'd MMM yyyy', locale),
          })}
        </p>
      )}
    </>
  )
}
