import { dating } from '@/features/family/pregnancyMath'
import { ancProgress, periodOutlook, postpartumDay, type AncVisitRecord, type Confidence } from './fertilityMath'
import { resolveDating, type DatingBasis } from './pregnancyPlan'
import { can, type Mode } from './modes'
import type { FertilityKey } from './messages'

/**
 * FE20 (owner overview) and FE18 (partner-visible summary) share one computation.
 *
 * `computeStatus` turns the owner's live records into a small, safe status: a
 * week number here carries the same estimate caveat the timeline does, a period
 * outlook stays a range, and nothing is a diagnosis. `domainSummary` shows the
 * owner all of it; `buildShareSnapshot` picks only the pieces the owner ticked to
 * share and denormalises them into a record the partner can read — because the
 * partner cannot read the private source rows, the snapshot is the only thing
 * that ever crosses, and it crosses only for the fields the owner chose.
 *
 * Kept free of any store import so there is no logic ↔ persistence cycle: callers
 * pass the handful of fields as `SummaryInput`.
 */

export interface SummaryInput {
  mode: Mode
  /** LMP from the running pregnancy record, or null when there is none. */
  lmpDate: string | null
  datingRow?: { basis: DatingBasis; usgDate?: string; usgWeeks?: number; usgDays?: number }
  /** Birth date from the postpartum record, or null. */
  birthDate: string | null
  ancVisits: AncVisitRecord[]
  cycleStarts: string[]
}

export interface FertStatus {
  mode: Mode
  /** Estimated completed weeks, with the usual "ask, don't trust" caveat. Null unless pregnant and in range. */
  week: number | null
  trimester: 1 | 2 | 3 | null
  /** Days since birth — a fact, not an estimate — when in nifas. */
  ppDay: number | null
  /** Next-period window. Always a range, never a bare date. */
  period: { from: string; to: string; confidence: Confidence; confidenceKey: FertilityKey } | null
  anc: { done: number; total: number } | null
}

/** The owner's own live status. Everything is derived, nothing is stored here. */
export function computeStatus(input: SummaryInput, today = new Date()): FertStatus {
  const { mode } = input

  let week: number | null = null
  let trimester: 1 | 2 | 3 | null = null
  let anc: FertStatus['anc'] = null
  if (can(mode, 'pregnancy') && input.lmpDate) {
    const source = resolveDating({
      basis: input.datingRow?.basis ?? 'lmp',
      lmpDate: input.lmpDate,
      usgDate: input.datingRow?.usgDate,
      usgWeeks: input.datingRow?.usgWeeks,
      usgDays: input.datingRow?.usgDays,
    })
    const d = dating(source.lmpDate, today)
    if (!d.outOfRange) {
      week = d.weeks
      trimester = d.trimester
    }
    const p = ancProgress(input.ancVisits)
    anc = { done: p.doneCount, total: p.total }
  }

  const ppDay =
    can(mode, 'postpartum') && input.birthDate ? postpartumDay(input.birthDate, today) : null

  let period: FertStatus['period'] = null
  if (can(mode, 'cycleEstimate') && input.cycleStarts.length > 0) {
    const out = periodOutlook(input.cycleStarts, today)
    if (out.range) {
      period = {
        from: out.range[0],
        to: out.range[1],
        confidence: out.confidence,
        confidenceKey: out.confidenceKey,
      }
    }
  }

  return { mode, week, trimester, ppDay, period, anc }
}

/** True when there is anything to summarise at all — otherwise the card says so. */
export function hasStatus(s: FertStatus): boolean {
  return s.week !== null || s.ppDay !== null || s.period !== null || s.anc !== null
}

// ---------------------------------------------------------------------------
// FE18 — what the owner explicitly shares
// ---------------------------------------------------------------------------

/**
 * The items the owner may opt to share, one flag each. Deliberately coarse: a
 * partner sees "sekitar minggu 24", never a raw BBT log or a scan date. `note` is
 * free text the owner writes *for* the partner — the only field that is not
 * derived from a health record.
 */
export const SHARE_KEYS = ['mode', 'pregnancy', 'postpartum', 'period', 'note'] as const
export type ShareKey = (typeof SHARE_KEYS)[number]

export interface ShareSnapshot {
  /** When the owner last refreshed this. Shown to the partner so stale is visible. */
  builtAt: string
  mode?: Mode
  week?: number
  trimester?: 1 | 2 | 3
  ppDay?: number
  periodFrom?: string
  periodTo?: string
  note?: string
}

/**
 * Denormalises the owner's current status into a snapshot, keeping only the
 * fields whose share flag is on. A field with no data (e.g. `pregnancy` ticked
 * but not pregnant) is simply omitted rather than shared as empty.
 */
export function buildShareSnapshot(
  input: SummaryInput,
  share: readonly ShareKey[],
  note: string,
  today = new Date(),
): ShareSnapshot {
  const status = computeStatus(input, today)
  const on = new Set(share)
  const snap: ShareSnapshot = { builtAt: today.toISOString() }

  if (on.has('mode')) snap.mode = status.mode
  if (on.has('pregnancy') && status.week !== null) {
    snap.week = status.week
    if (status.trimester !== null) snap.trimester = status.trimester
  }
  if (on.has('postpartum') && status.ppDay !== null) snap.ppDay = status.ppDay
  if (on.has('period') && status.period) {
    snap.periodFrom = status.period.from
    snap.periodTo = status.period.to
  }
  const trimmed = note.trim()
  if (on.has('note') && trimmed) snap.note = trimmed

  return snap
}

/** True when the snapshot carries anything the partner would actually see. */
export function snapshotHasContent(snap: ShareSnapshot): boolean {
  return (
    snap.mode !== undefined ||
    snap.week !== undefined ||
    snap.ppDay !== undefined ||
    snap.periodFrom !== undefined ||
    snap.note !== undefined
  )
}
