import { useState } from 'react'
import { Link } from 'react-router-dom'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, VisibilityBadge } from '@/components/ui'
import { useI18n } from '@/i18n'
import { fmtDate, formatRupiah } from '@/i18n/format'
import { addFinance, useFinance } from '@/features/finance/store'
import {
  ART_METHODS,
  ART_APPT_TYPES,
  PROMIL_CATEGORY,
  artPhaseTrack,
  artWait,
  promilSummary,
  vitalsSummary,
  type ArtApptType,
} from './advancedMath'
import { addFert, patchFert, removeFert, saveMemorial, type FertilityData } from './store'

const today = () => format(new Date(), 'yyyy-MM-dd')
const num = (s: string): number | undefined => (s.trim() === '' ? undefined : Number(s))

/**
 * The four later features (FE13–FE16). Same discipline as the rest of the
 * module: every screen renders real IndexedDB state through the store, every
 * estimate stays a range, and nothing here diagnoses, schedules, or promises an
 * outcome. Copy lives in `messages.ts`; these components only call `t()`.
 */

// ---------------------------------------------------------------------------
// FE13 — weight & blood pressure, shown as ranges
// ---------------------------------------------------------------------------

export function Vitals({ me, data }: { me: string; data: FertilityData }) {
  const { t, locale } = useI18n()
  const [date, setDate] = useState(today())
  const [weight, setWeight] = useState('')
  const [sistol, setSistol] = useState('')
  const [diastol, setDiastol] = useState('')

  const logs = data.vitals.map((v) => ({
    date: v.date,
    weightKg: v.weightKg,
    sistol: v.sistol,
    diastol: v.diastol,
  }))
  const sum = vitalsSummary(logs)

  const clean = num(weight) === undefined && num(sistol) === undefined && num(diastol) === undefined
  async function log() {
    if (clean) return
    await addFert(me, {
      kind: 'fert_vital',
      date: date || today(),
      weightKg: num(weight),
      sistol: num(sistol),
      diastol: num(diastol),
    })
    setWeight('')
    setSistol('')
    setDiastol('')
  }

  return (
    <Card title={t('fertility.vital.title')} icon="health" hint={t('fertility.vital.hint')}>
      <div className="stack stack--tight">
        <Field label={t('fertility.vital.date')}>
          {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
        </Field>
        <Field label={t('fertility.vital.weight')}>
          {(p) => (
            <input
              {...p}
              type="number"
              inputMode="decimal"
              value={weight}
              onChange={(e) => setWeight(e.target.value)}
            />
          )}
        </Field>
        <div className="row" style={{ gap: 'var(--space-2)', flexWrap: 'wrap' }}>
          <span className="grow">
            <Field label={t('fertility.vital.sistol')}>
              {(p) => (
                <input
                  {...p}
                  type="number"
                  inputMode="numeric"
                  value={sistol}
                  onChange={(e) => setSistol(e.target.value)}
                />
              )}
            </Field>
          </span>
          <span className="grow">
            <Field label={t('fertility.vital.diastol')}>
              {(p) => (
                <input
                  {...p}
                  type="number"
                  inputMode="numeric"
                  value={diastol}
                  onChange={(e) => setDiastol(e.target.value)}
                />
              )}
            </Field>
          </span>
        </div>
        <button className="btn btn--block" disabled={clean} onClick={log}>
          <Icon name="plus" size={16} /> {t('fertility.vital.add')}
        </button>

        {/* Ranges, deliberately never a single "your BP is X" verdict. */}
        {sum.weight && (
          <p>
            <strong>
              {t('fertility.vital.weightRange', {
                min: sum.weight.min,
                max: sum.weight.max,
                first: sum.weight.first,
                last: sum.weight.last,
                n: sum.weight.count,
              })}
            </strong>
          </p>
        )}
        {sum.sistol && sum.diastol && (
          <p>
            <strong>
              {t('fertility.vital.bpRange', {
                sisMin: sum.sistol.min,
                sisMax: sum.sistol.max,
                diaMin: sum.diastol.min,
                diaMax: sum.diastol.max,
                n: Math.max(sum.sistol.count, sum.diastol.count),
              })}
            </strong>
          </p>
        )}
        <p className="card__hint">{t(sum.messageKey)}</p>
        <p className="disclaimer">{t('fertility.vital.caveat')}</p>

        {data.vitals.length > 0 && (
          <ul className="list">
            {data.vitals.slice(0, 8).map((v) => (
              <li key={v.id} className="list__item">
                <span className="grow" style={{ fontSize: 14 }}>
                  {fmtDate(v.date, 'd MMM yyyy', locale)}
                  {v.weightKg !== undefined && ` · ${v.weightKg} kg`}
                  {v.sistol !== undefined && v.diastol !== undefined && ` · ${v.sistol}/${v.diastol}`}
                </span>
                <button
                  className="btn btn--ghost btn--sm"
                  aria-label={t('fertility.delete')}
                  onClick={() => removeFert(v.id, me)}
                >
                  <Icon name="close" size={16} />
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </Card>
  )
}

// ---------------------------------------------------------------------------
// FE14 + FE15 — IVF / IUI cycle, appointments, the wait, and the costs
// ---------------------------------------------------------------------------

export function Art({ me, data }: { me: string; data: FertilityData }) {
  const { t } = useI18n()
  const art = data.art

  if (!art) {
    return (
      <Card title={t('fertility.art.title')} icon="cycle" hint={t('fertility.art.hint')}>
        <p>{t('fertility.art.body')}</p>
        <div className="row" style={{ gap: 'var(--space-2)', marginTop: 'var(--space-3)' }}>
          {ART_METHODS.map((m) => (
            <button
              key={m}
              className="btn btn--soft btn--sm"
              onClick={() => addFert(me, { kind: 'fert_art', method: m })}
            >
              {t('fertility.art.enable')}: {t(`fertility.art.method.${m}`)}
            </button>
          ))}
        </div>
        <p className="disclaimer" style={{ marginTop: 'var(--space-3)' }}>
          {t('fertility.art.caveat')}
        </p>
      </Card>
    )
  }

  return (
    <>
      <ArtCycle me={me} data={data} />
      <ArtCosts me={me} />
    </>
  )
}

function ArtCycle({ me, data }: { me: string; data: FertilityData }) {
  const { t, locale } = useI18n()
  const art = data.art!
  const track = artPhaseTrack(art.method, art.phase)
  const wait =
    art.procedureDate ? artWait(art.procedureDate, art.betaDate) : null

  const [apptDate, setApptDate] = useState(today())
  const [apptType, setApptType] = useState<ArtApptType>('konsultasi')
  const [apptNote, setApptNote] = useState('')

  async function addAppt() {
    await addFert(me, {
      kind: 'fert_art_appt',
      date: apptDate || today(),
      typeId: apptType,
      done: false,
      ...(apptNote.trim() ? { note: apptNote.trim() } : {}),
    })
    setApptNote('')
  }

  return (
    <Card
      title={`${t('fertility.art.title')} · ${t(`fertility.art.method.${art.method}`)}`}
      icon="cycle"
      hint={t('fertility.art.hint')}
      action={
        <button
          className="btn btn--ghost btn--sm"
          onClick={() => removeFert(art.id, me)}
        >
          {t('fertility.art.clear')}
        </button>
      }
    >
      <div className="stack stack--tight">
        {/* Phases — the owner marks where they are; nothing advances by itself. */}
        <strong style={{ fontSize: 13 }}>{t('fertility.art.phaseTitle')}</strong>
        <p className="card__hint">{t('fertility.art.phaseHint')}</p>
        <div className="choices" role="radiogroup" aria-label={t('fertility.art.phaseTitle')}>
          {track.map((step) => (
            <button
              key={step.id}
              type="button"
              role="radio"
              aria-checked={step.state === 'now'}
              className="choice"
              onClick={() => patchFert(art.id, { phase: step.id })}
            >
              <span className="grow choice__title">{t(`fertility.art.phase.${step.id}`)}</span>
              <span className="card__hint">{t(`fertility.art.phase.state.${step.state}`)}</span>
              {step.state === 'now' && <Icon name="check" size={18} />}
            </button>
          ))}
        </div>

        {/* The two-week wait — counts up, never down. */}
        <strong style={{ fontSize: 13, marginTop: 'var(--space-3)' }}>
          {t('fertility.art.wait.title')}
        </strong>
        <Field label={t('fertility.art.wait.procedure')}>
          {(p) => (
            <input
              {...p}
              type="date"
              value={art.procedureDate ?? ''}
              onChange={(e) => patchFert(art.id, { procedureDate: e.target.value || undefined })}
            />
          )}
        </Field>
        <Field label={t('fertility.art.wait.beta')} hint={t('fertility.art.wait.betaHint')}>
          {(p) => (
            <input
              {...p}
              type="date"
              value={art.betaDate ?? ''}
              onChange={(e) => patchFert(art.id, { betaDate: e.target.value || undefined })}
            />
          )}
        </Field>
        {wait && (
          <>
            {wait.daysSince >= 0 && <p>{t('fertility.art.wait.daysSince', { n: wait.daysSince })}</p>}
            {wait.betaDate && (
              <p className="card__hint">
                {t('fertility.art.wait.betaOn', { date: fmtDate(wait.betaDate, 'd MMM yyyy', locale) })}
              </p>
            )}
            <p>{t(wait.statusKey)}</p>
            <p className="card__hint">{t('fertility.art.wait.gentle')}</p>
          </>
        )}

        {/* Appointments — a structure, dates from the clinic. */}
        <strong style={{ fontSize: 13, marginTop: 'var(--space-3)' }}>
          {t('fertility.art.appt.title')}
        </strong>
        <p className="card__hint">{t('fertility.art.appt.hint')}</p>
        <div className="row" style={{ gap: 'var(--space-2)', flexWrap: 'wrap' }}>
          <span className="grow">
            <Field label={t('fertility.art.appt.date')}>
              {(p) => (
                <input {...p} type="date" value={apptDate} onChange={(e) => setApptDate(e.target.value)} />
              )}
            </Field>
          </span>
          <span className="grow">
            <Field label={t('fertility.art.appt.title')}>
              {(p) => (
                <select {...p} value={apptType} onChange={(e) => setApptType(e.target.value as ArtApptType)}>
                  {ART_APPT_TYPES.map((ty) => (
                    <option key={ty} value={ty}>
                      {t(`fertility.art.appt.type.${ty}`)}
                    </option>
                  ))}
                </select>
              )}
            </Field>
          </span>
        </div>
        <Field label={t('fertility.art.appt.note')}>
          {(p) => (
            <input {...p} value={apptNote} onChange={(e) => setApptNote(e.target.value)} />
          )}
        </Field>
        <button className="btn btn--soft btn--block" onClick={addAppt}>
          <Icon name="plus" size={16} /> {t('fertility.art.appt.add')}
        </button>

        {data.artAppts.length === 0 ? (
          <p className="card__hint">{t('fertility.art.appt.none')}</p>
        ) : (
          <ul className="list">
            {data.artAppts.map((a) => (
              <li key={a.id} className="list__item">
                <input
                  type="checkbox"
                  checked={a.done}
                  aria-label={t('fertility.art.appt.done')}
                  onChange={() => patchFert(a.id, { done: !a.done })}
                />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{t(`fertility.art.appt.type.${a.typeId}`)}</strong>
                  <span className="card__hint">
                    {fmtDate(a.date, 'd MMM yyyy', locale)}
                    {a.note ? ` · ${a.note}` : ''}
                  </span>
                </span>
                <button
                  className="btn btn--ghost btn--sm"
                  aria-label={t('fertility.delete')}
                  onClick={() => removeFert(a.id, me)}
                >
                  <Icon name="close" size={16} />
                </button>
              </li>
            ))}
          </ul>
        )}

        <p className="disclaimer">{t('fertility.art.caveat')}</p>
      </div>
    </Card>
  )
}

/**
 * FE15 — IVF costs, kept in the finance domain.
 *
 * A cost is an ordinary finance ledger row, tagged `promil` and forced private,
 * so it appears in Finance under the owner's own money and the partner never
 * sees an amount unless the owner shares it there. This screen reads only the
 * current viewer's own rows — the finance read gate does the hiding.
 */
function ArtCosts({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const accounts = useFinance('accounts', me)
  const ledger = useFinance('ledger', me)

  const costs = (ledger ?? []).filter((l) => l.category === PROMIL_CATEGORY && !l.deletedAt)
  const sum = promilSummary(costs.map((c) => ({ amount: c.amount, planned: c.planned })))

  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [planned, setPlanned] = useState(false)

  const own = (accounts ?? []).filter((a) => a.ownerProfileId === me && !a.deletedAt)
  const [accountId, setAccountId] = useState('')
  const chosen = accountId || own[0]?.id

  async function log() {
    const n = num(amount)
    if (!chosen || !n || !label.trim()) return
    // Negative: money out. Private envelope + inherited-from-account: partner
    // cannot read it at all until the owner shares in Finance.
    await addFinance(
      'ledger',
      me,
      'C1_personal',
      {
        kind: 'ledger',
        accountId: chosen,
        label: label.trim(),
        amount: -Math.abs(n),
        category: PROMIL_CATEGORY,
        date: today(),
        planned,
      },
      { visibility: 'private' },
    )
    setLabel('')
    setAmount('')
    setPlanned(false)
  }

  return (
    <Card title={t('fertility.cost.title')} icon="money" hint={t('fertility.cost.hint')}>
      <div className="stack stack--tight">
        <p className="card__hint">{t('fertility.cost.body')}</p>

        {own.length === 0 ? (
          <EmptyState
            icon="money"
            title={t('fertility.cost.none')}
            hint={t('fertility.cost.body')}
            action={
              <Link to="/uang" className="btn btn--soft btn--sm">
                <Icon name="money" size={16} /> {t('fertility.cost.openFinance')}
              </Link>
            }
          />
        ) : (
          <>
            {own.length > 1 && (
              <Field label={t('fertility.cost.openFinance')}>
                {(p) => (
                  <select {...p} value={chosen} onChange={(e) => setAccountId(e.target.value)}>
                    {own.map((a) => (
                      <option key={a.id} value={a.id}>
                        {a.name}
                      </option>
                    ))}
                  </select>
                )}
              </Field>
            )}
            <Field label={t('fertility.cost.label')}>
              {(p) => <input {...p} value={label} onChange={(e) => setLabel(e.target.value)} />}
            </Field>
            <Field label={t('fertility.cost.amount')}>
              {(p) => (
                <input
                  {...p}
                  type="number"
                  inputMode="numeric"
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                />
              )}
            </Field>
            <label className="row" style={{ gap: 'var(--space-2)', fontSize: 14, minHeight: 34 }}>
              <input type="checkbox" checked={planned} onChange={(e) => setPlanned(e.target.checked)} />
              <span>{t('fertility.cost.planned')}</span>
            </label>
            <button className="btn btn--block" onClick={log}>
              <Icon name="plus" size={16} /> {t('fertility.cost.add')}
            </button>
          </>
        )}

        <p>
          <strong>{t('fertility.cost.actualTotal', { amount: formatRupiah(sum.actualTotal, locale) })}</strong>
        </p>
        {sum.plannedTotal > 0 && (
          <p className="card__hint">
            {t('fertility.cost.plannedTotal', { amount: formatRupiah(sum.plannedTotal, locale) })}
          </p>
        )}
        <p className="card__hint">{t('fertility.cost.count', { n: sum.count })}</p>
        <p className="card__hint">{t(sum.messageKey)}</p>

        <p className="row" style={{ gap: 'var(--space-2)' }}>
          <VisibilityBadge visibility="private" />
          <span className="card__hint grow">{t('fertility.cost.privateNote')}</span>
        </p>
      </div>
    </Card>
  )
}

// ---------------------------------------------------------------------------
// FE16 — the opt-in memorial
// ---------------------------------------------------------------------------

export function Memorial({ me, data }: { me: string; data: FertilityData }) {
  const { t } = useI18n()
  const mem = data.memorial

  if (!mem) {
    return (
      <Card title={t('fertility.memorial.title')} icon="memories" hint={t('fertility.memorial.hint')}>
        <p>{t('fertility.memorial.body')}</p>
        <button
          className="btn btn--soft btn--block"
          style={{ marginTop: 'var(--space-3)' }}
          onClick={() => saveMemorial(me, undefined, {})}
        >
          <Icon name="memories" size={16} /> {t('fertility.memorial.enable')}
        </button>
        <p className="card__hint" style={{ marginTop: 'var(--space-3)' }}>
          {t('fertility.memorial.noPrompt')}
        </p>
      </Card>
    )
  }

  return (
    <Card
      title={t('fertility.memorial.title')}
      icon="memories"
      hint={t('fertility.memorial.hint')}
      action={
        <button className="btn btn--ghost btn--sm" onClick={() => removeFert(mem.id, me)}>
          {t('fertility.memorial.remove')}
        </button>
      }
    >
      <div className="stack stack--tight">
        <Field label={t('fertility.memorial.name')} hint={t('fertility.memorial.nameHint')}>
          {(p) => (
            <input
              {...p}
              defaultValue={mem.name ?? ''}
              onBlur={(e) => saveMemorial(me, mem, { name: e.target.value || undefined })}
            />
          )}
        </Field>
        {/* No "how far along" anywhere — a plain optional date, nothing computed from it. */}
        <Field label={t('fertility.memorial.date')}>
          {(p) => (
            <input
              {...p}
              type="date"
              defaultValue={mem.date ?? ''}
              onBlur={(e) => saveMemorial(me, mem, { date: e.target.value || undefined })}
            />
          )}
        </Field>
        <Field label={t('fertility.memorial.words')} hint={t('fertility.memorial.wordsHint')}>
          {(p) => (
            <textarea
              {...p}
              defaultValue={mem.words ?? ''}
              onBlur={(e) => saveMemorial(me, mem, { words: e.target.value || undefined })}
            />
          )}
        </Field>
        <p className="row" style={{ gap: 'var(--space-2)' }}>
          <VisibilityBadge visibility="private" />
          <span className="card__hint grow">{t('fertility.memorial.private')}</span>
        </p>
        <p className="card__hint">{t('fertility.memorial.noPrompt')}</p>
      </div>
    </Card>
  )
}
