import { Link } from 'react-router-dom'
import { useState } from 'react'
import { Card, EmptyState, Field, VisibilityBadge } from '@/components/ui'
import { useOwned } from '@/db/hooks'
import type { CycleLog } from '@/types/domain'
import { useI18n } from '@/i18n'
import { fmtDate } from '@/i18n/format'
import {
  SHARE_KEYS,
  buildShareSnapshot,
  computeStatus,
  hasStatus,
  snapshotHasContent,
  type ShareKey,
  type ShareSnapshot,
  type SummaryInput,
} from './summary'
import { saveShare, type FertilityData, type Of } from './store'

/**
 * FE18 (partner-visible summary), FE19 (the un-dismissible disclaimer), and FE20
 * (owner domain summary + backup coverage) — the three cross-cutting screens.
 *
 * All three obey the same privacy model as the rest of the module: the owner
 * summary is computed from the owner's own live rows, the partner summary reads
 * only the one `fert_share` record the owner widened, and nothing here invents a
 * provider, a diagnosis, or a bare date.
 */

/**
 * FE19 — the medical disclaimer, rendered on every fertility screen and carrying
 * no dismiss control. It is a plain paragraph on purpose: there is nothing to
 * click, so there is no state in which it is gone.
 */
export function Disclaimer() {
  const { t } = useI18n()
  return (
    <p className="disclaimer" role="note">
      {t('fertility.disclaimer')}
    </p>
  )
}

function inputFrom(data: FertilityData, cycleStarts: string[]): SummaryInput {
  return {
    mode: data.mode,
    lmpDate: data.pregnancies[0]?.lmpDate ?? null,
    datingRow: data.datingRow
      ? {
          basis: data.datingRow.basis,
          usgDate: data.datingRow.usgDate,
          usgWeeks: data.datingRow.usgWeeks,
          usgDays: data.datingRow.usgDays,
        }
      : undefined,
    birthDate: data.births[0]?.date ?? null,
    ancVisits: data.ancVisits.map((v) => ({ slotId: v.slotId, withDoctor: v.withDoctor })),
    cycleStarts,
  }
}

// ---------------------------------------------------------------------------
// FE20 — the owner's at-a-glance status, and where the data lives
// ---------------------------------------------------------------------------

export function DomainSummary({ me, data }: { me: string; data: FertilityData }) {
  const { t, locale } = useI18n()
  const cycles = useOwned<CycleLog>('cycles', me)
  const status = computeStatus(inputFrom(data, (cycles ?? []).map((c) => c.startDate)))

  return (
    <Card title={t('fertility.summary.title')} icon="health" hint={t('fertility.summary.hint')}>
      <div className="stack stack--tight">
        <p>
          <strong>{t('fertility.summary.mode', { mode: t(`fertility.mode.${status.mode}`) })}</strong>
        </p>

        {!hasStatus(status) ? (
          <p className="card__hint">{t('fertility.summary.empty')}</p>
        ) : (
          <ul style={{ margin: 0, paddingLeft: "1.2em" }}>
            {status.week !== null && (
              <li>
                {t('fertility.summary.week', { n: status.week })}
                {status.trimester !== null && ` · ${t('fertility.timeline.trimester', { n: status.trimester })}`}
              </li>
            )}
            {status.anc && (
              <li>{t('fertility.summary.anc', { done: status.anc.done, total: status.anc.total })}</li>
            )}
            {status.ppDay !== null && <li>{t('fertility.pp.day', { n: status.ppDay })}</li>}
            {status.period && (
              <li>
                {t('fertility.outlook.range', {
                  from: fmtDate(status.period.from, 'd MMM', locale),
                  to: fmtDate(status.period.to, 'd MMM yyyy', locale),
                })}
                {` · ${t(status.period.confidenceKey)}`}
              </li>
            )}
          </ul>
        )}

        <p className="card__hint">
          {t('fertility.summary.backup')}{' '}
          <Link to="/pengaturan">{t('fertility.summary.backupLink')}</Link>
        </p>
      </div>
    </Card>
  )
}

// ---------------------------------------------------------------------------
// FE18 — the owner picks what the partner may see
// ---------------------------------------------------------------------------

const SHARE_ICON = 'shared' as const

export function ShareControl({ me, data }: { me: string; data: FertilityData }) {
  const { t } = useI18n()
  const cycles = useOwned<CycleLog>('cycles', me)
  const mine = data.shares.find((s) => s.ownerProfileId === me)

  const [share, setShare] = useState<ShareKey[]>(mine?.share ?? [])
  const [note, setNote] = useState(mine?.note ?? '')

  const input = inputFrom(data, (cycles ?? []).map((c) => c.startDate))
  // Live preview: exactly what the partner would read given the current ticks.
  const preview = buildShareSnapshot(input, share, note)

  async function commit(nextShare: ShareKey[], nextNote: string) {
    const snapshot = buildShareSnapshot(input, nextShare, nextNote)
    // ponytail: relies on the live query re-supplying `mine` between clicks so a
    // first-ever toggle creates one row, not two. Human click cadence covers it.
    await saveShare(
      me,
      mine,
      { share: nextShare, note: nextNote || undefined, snapshot },
      snapshotHasContent(snapshot),
    )
  }

  function toggle(k: ShareKey) {
    const next = share.includes(k) ? share.filter((x) => x !== k) : [...share, k]
    setShare(next)
    void commit(next, note)
  }

  const sharing = snapshotHasContent(preview)

  return (
    <Card title={t('fertility.share.title')} icon={SHARE_ICON} hint={t('fertility.share.hint')}>
      <div className="stack stack--tight">
        <p className="card__hint">{t('fertility.share.body')}</p>

        <fieldset style={{ border: 0, padding: 0, margin: 0 }}>
          <legend className="visually-hidden">{t('fertility.share.title')}</legend>
          <div className="stack stack--tight">
            {SHARE_KEYS.map((k) => (
              <label
                key={k}
                className="row"
                style={{ gap: 'var(--space-2)', fontSize: 14, minHeight: 34 }}
              >
                <input type="checkbox" checked={share.includes(k)} onChange={() => toggle(k)} />
                <span className="grow">{t(`fertility.share.item.${k}`)}</span>
              </label>
            ))}
          </div>
        </fieldset>

        {share.includes('note') && (
          <Field label={t('fertility.share.note')} hint={t('fertility.share.noteHint')}>
            {(p) => (
              <textarea
                {...p}
                defaultValue={note}
                onBlur={(e) => {
                  setNote(e.target.value)
                  void commit(share, e.target.value)
                }}
              />
            )}
          </Field>
        )}

        <div className="stack stack--tight" style={{ marginTop: 'var(--space-2)' }}>
          <strong style={{ fontSize: 13 }}>{t('fertility.share.preview')}</strong>
          {sharing ? (
            <SnapshotLines snap={preview} />
          ) : (
            <p className="card__hint">{t('fertility.share.previewNone')}</p>
          )}
        </div>

        <p className="row" style={{ gap: 'var(--space-2)' }}>
          <VisibilityBadge visibility={sharing ? 'shared' : 'private'} />
          <span className="card__hint grow">
            {sharing ? t('fertility.share.isShared') : t('fertility.share.isPrivate')}
          </span>
        </p>
      </div>
    </Card>
  )
}

// ---------------------------------------------------------------------------
// FE18 — what the partner actually sees
// ---------------------------------------------------------------------------

/** Renders one shared snapshot. Owned by the partner-summary and the preview. */
function SnapshotLines({ snap }: { snap: ShareSnapshot }) {
  const { t, locale } = useI18n()
  return (
    <ul style={{ margin: 0, paddingLeft: "1.2em" }}>
      {snap.mode !== undefined && (
        <li>{t('fertility.summary.mode', { mode: t(`fertility.mode.${snap.mode}`) })}</li>
      )}
      {snap.week !== undefined && (
        <li>
          {t('fertility.summary.week', { n: snap.week })}
          {snap.trimester !== undefined && ` · ${t('fertility.timeline.trimester', { n: snap.trimester })}`}
        </li>
      )}
      {snap.ppDay !== undefined && <li>{t('fertility.pp.day', { n: snap.ppDay })}</li>}
      {snap.periodFrom !== undefined && snap.periodTo !== undefined && (
        <li>
          {t('fertility.outlook.range', {
            from: fmtDate(snap.periodFrom, 'd MMM', locale),
            to: fmtDate(snap.periodTo, 'd MMM yyyy', locale),
          })}
        </li>
      )}
      {snap.note !== undefined && <li>{snap.note}</li>}
    </ul>
  )
}

/**
 * The card the partner sees. It renders only what the owner shared — one
 * `fert_share` row that reached this viewer through the read gate. There is no
 * path here to the owner's private rows; if the owner shares nothing, this
 * component is never rendered.
 */
export function PartnerSummary({ share }: { share: Of<'fert_share'> }) {
  const { t, locale } = useI18n()
  const snap = share.snapshot

  return (
    <Card title={t('fertility.partner.title')} icon={SHARE_ICON} hint={t('fertility.partner.hint')}>
      <div className="stack stack--tight">
        {snapshotHasContent(snap) ? (
          <SnapshotLines snap={snap} />
        ) : (
          <EmptyState icon="shared" title={t('fertility.partner.none')} />
        )}
        {snap.builtAt && (
          <p className="card__hint">
            {t('fertility.partner.updated', {
              date: fmtDate(snap.builtAt.slice(0, 10), 'd MMM yyyy', locale),
            })}
          </p>
        )}
        <Disclaimer />
      </div>
    </Card>
  )
}
