import { useEffect, useState } from 'react'
import { format } from 'date-fns'
import { Icon, type IconName } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { db, newEnvelope } from '@/db/db'
import { dating } from '@/features/family/pregnancyMath'
import { useI18n } from '@/i18n'
import { fmtDate } from '@/i18n/format'
import {
  DANGER_SIGNS,
  P4K_FIELDS,
  TTD_TARGET,
  ancProgress,
  ancSchedule,
  ancSlotState,
  contractionSummary,
  kickBaseline,
  p4kProgress,
  triage,
  ttdAdherence,
  type AncSlot,
  type AncSlotId,
  type P4kField,
  type TriageLevel,
} from './fertilityMath'
import {
  ANC_MEASURES,
  filledMeasures,
  pregnancyTimeline,
  resolveDating,
  ttdStreak,
  visitRecordState,
  type AncMeasureId,
  type AncMeasures,
  type DatingAssumption,
  type DatingBasis,
  type TimelineWeek,
} from './pregnancyPlan'
import {
  addFert,
  logTtd,
  patchFert,
  removeFert,
  saveAncVisit,
  saveDating,
  type FertilityData,
  type Of,
} from './store'

const today = () => format(new Date(), 'yyyy-MM-dd')

/**
 * Kehamilan.
 *
 * Reuses the existing `pregnancy` family record and `pregnancyMath.dating()`
 * for the week counter, then adds what Indonesian antenatal care actually runs
 * on: the K6 visit minimum, tablet tambah darah, and P4K.
 *
 * The triage block is the sharp edge here. It sorts danger signs by *how soon
 * to get in touch* and never by what might be wrong, it cannot be combined into
 * a higher level, and it says out loud that the app cannot diagnose.
 */
export default function Pregnancy({ me, data }: { me: string; data: FertilityData }) {
  const { t, locale } = useI18n()
  const [addOpen, setAddOpen] = useState(false)
  const [lmp, setLmp] = useState(today())

  const preg = data.pregnancies[0]

  async function createPregnancy() {
    await db.family.add({
      ...newEnvelope(me, 'C4_health'),
      kind: 'pregnancy',
      lmpDate: lmp,
      status: 'jalan',
    } as never)
    setAddOpen(false)
  }

  if (!preg) {
    return (
      <>
        <Card title={t('fertility.mode.hamil')} icon="pregnancy">
          <EmptyState
            icon="pregnancy"
            title={t('fertility.preg.none')}
            hint={t('fertility.preg.noneHint')}
            action={
              <button className="btn btn--sm" onClick={() => setAddOpen(true)}>
                <Icon name="plus" size={16} /> {t('fertility.preg.add')}
              </button>
            }
          />
        </Card>
        <Sheet open={addOpen} onClose={() => setAddOpen(false)} title={t('fertility.preg.sheet')}>
          <div className="stack">
            <Field label={t('fertility.preg.lmp')} hint={t('fertility.preg.lmpHint')}>
              {(p) => <input {...p} type="date" value={lmp} onChange={(e) => setLmp(e.target.value)} />}
            </Field>
            <button className="btn btn--block" onClick={createPregnancy}>
              {t('common.save')}
            </button>
          </div>
        </Sheet>
      </>
    )
  }

  // FE5 — one assumption, resolved once, and every date below derives from it.
  const assumption: DatingAssumption = {
    basis: data.datingRow?.basis ?? 'lmp',
    lmpDate: preg.lmpDate,
    usgDate: data.datingRow?.usgDate,
    usgWeeks: data.datingRow?.usgWeeks,
    usgDays: data.datingRow?.usgDays,
  }
  const source = resolveDating(assumption)
  const d = dating(source.lmpDate)
  const slots = ancSchedule(source.lmpDate)

  return (
    <>
      <Card title={t('fertility.mode.hamil')} icon="pregnancy">
        <div className="stack stack--tight">
          <p>
            <strong>
              {/* Own keys rather than `fam.week`: that one names a trimester,
                  and this module's trimester bands are the Buku KIA ones. */}
              {d.outOfRange
                ? t('fertility.preg.outOfRange')
                : t('fertility.preg.week', { weeks: d.weeks, days: d.days })}
            </strong>
          </p>
          {!d.outOfRange && (
            <p className="card__hint">
              {t('fertility.preg.due', { date: fmtDate(d.estimatedDueDate, 'd MMMM yyyy', locale) })}
            </p>
          )}
          <p className="disclaimer">{t('fertility.preg.caveat')}</p>
        </div>
      </Card>

      <Dating me={me} preg={preg} assumption={assumption} row={data.datingRow} />
      <Timeline lmpDate={source.lmpDate} />

      <Anc me={me} slots={slots} visits={data.ancVisits} />
      <Ttd me={me} rows={data.ttd} />
      <P4k me={me} rows={data.p4k} />
      <Triage me={me} history={data.triages} />
      <Kicks me={me} sessions={data.kicks} />
      <Contractions me={me} rows={data.contractions} />
    </>
  )
}

// ---------------------------------------------------------------------------

/**
 * FE5 — the assumption, stated out loud.
 *
 * Every week number, every ANC window, and the due date all hang off one date,
 * and that date is a guess. So it is named on screen with the thing it came
 * from, it is editable in two taps, and when the two possible sources disagree
 * the gap between them is shown — without the app picking a winner, because
 * choosing between a period date and a dating scan is a clinical call.
 */
function Dating({
  me,
  preg,
  assumption,
  row,
}: {
  me: string
  preg: { id: string; lmpDate: string }
  assumption: DatingAssumption
  row: Of<'fert_dating'> | undefined
}) {
  const { t, locale } = useI18n()
  const [open, setOpen] = useState(false)
  const s = resolveDating(assumption)
  const shown = s.basis === 'usg' ? (assumption.usgDate ?? preg.lmpDate) : preg.lmpDate

  return (
    <>
      <Card
        title={t('fertility.dating.title')}
        icon="info"
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="settings" size={16} /> {t('fertility.dating.edit')}
          </button>
        }
      >
        <div className="stack stack--tight">
          <p>
            <strong>
              {t(s.labelKey, {
                date: fmtDate(shown, 'd MMMM yyyy', locale),
                weeks: assumption.usgWeeks ?? 0,
                days: assumption.usgDays ?? 0,
              })}
            </strong>
          </p>
          {s.fellBack && <p className="card__hint">{t('fertility.dating.fellBack')}</p>}
          {s.shiftDays !== null && (
            <p className="card__hint">
              {s.shiftDays === 0
                ? t('fertility.dating.same')
                : t('fertility.dating.shift', { n: Math.abs(s.shiftDays) })}
            </p>
          )}
          <p className="disclaimer">{t('fertility.dating.caveat')}</p>
        </div>
      </Card>

      <Sheet open={open} onClose={() => setOpen(false)} title={t('fertility.dating.sheet')}>
        {open && (
          <DatingForm
            assumption={assumption}
            onSave={async (next) => {
              // The period date stays on the record it already lives on; only
              // the scan and the choice are this feature's own row.
              if (next.lmpDate !== preg.lmpDate) await patchFert(preg.id, { lmpDate: next.lmpDate })
              await saveDating(me, row, {
                basis: next.basis,
                ...(next.usgDate ? { usgDate: next.usgDate } : {}),
                ...(next.usgWeeks === undefined ? {} : { usgWeeks: next.usgWeeks }),
                ...(next.usgDays === undefined ? {} : { usgDays: next.usgDays }),
              })
              setOpen(false)
            }}
          />
        )}
      </Sheet>
    </>
  )
}

/** Empty string means "not entered"; a zero week is a real answer, so parse carefully. */
const num = (s: string): number | undefined => (s.trim() === '' ? undefined : Number(s))

function DatingForm({
  assumption,
  onSave,
}: {
  assumption: DatingAssumption
  onSave: (next: DatingAssumption) => void
}) {
  const { t } = useI18n()
  const [basis, setBasis] = useState<DatingBasis>(assumption.basis)
  const [lmpDate, setLmp] = useState(assumption.lmpDate)
  const [usgDate, setUsgDate] = useState(assumption.usgDate ?? '')
  const [weeks, setWeeks] = useState(assumption.usgWeeks?.toString() ?? '')
  const [days, setDays] = useState(assumption.usgDays?.toString() ?? '')

  return (
    <div className="stack">
      <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
        <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>
          {t('fertility.dating.basis')}
        </legend>
        {(['lmp', 'usg'] as const).map((b) => (
          <label key={b} className="row" style={{ gap: 'var(--space-3)', fontSize: 14, minHeight: 34 }}>
            <input
              type="radio"
              name="fert-dating-basis"
              checked={basis === b}
              onChange={() => setBasis(b)}
            />
            <span>{t(`fertility.dating.basis.${b}`)}</span>
          </label>
        ))}
      </fieldset>

      <Field label={t('fertility.preg.lmp')} hint={t('fertility.preg.lmpHint')}>
        {(p) => <input {...p} type="date" value={lmpDate} onChange={(e) => setLmp(e.target.value)} />}
      </Field>
      <Field label={t('fertility.dating.usgDate')}>
        {(p) => <input {...p} type="date" value={usgDate} onChange={(e) => setUsgDate(e.target.value)} />}
      </Field>
      <div className="row" style={{ gap: 'var(--space-2)', flexWrap: 'wrap' }}>
        <span className="grow">
          <Field label={t('fertility.dating.usgWeeks')}>
            {(p) => (
              <input
                {...p}
                type="number"
                inputMode="numeric"
                min={0}
                max={42}
                value={weeks}
                onChange={(e) => setWeeks(e.target.value)}
              />
            )}
          </Field>
        </span>
        <span className="grow">
          <Field label={t('fertility.dating.usgDays')}>
            {(p) => (
              <input
                {...p}
                type="number"
                inputMode="numeric"
                min={0}
                max={6}
                value={days}
                onChange={(e) => setDays(e.target.value)}
              />
            )}
          </Field>
        </span>
      </div>

      <button
        className="btn btn--block"
        onClick={() =>
          onSave({
            basis,
            lmpDate,
            ...(usgDate ? { usgDate } : {}),
            usgWeeks: num(weeks),
            usgDays: num(days),
          })
        }
      >
        {t('common.save')}
      </button>
      <p className="disclaimer">{t('fertility.dating.caveat')}</p>
    </div>
  )
}

// ---------------------------------------------------------------------------

const WEEK_ICON: Record<TimelineWeek['state'], IconName> = {
  past: 'check',
  now: 'health',
  ahead: 'calendar',
}

/**
 * FE5 — the timeline.
 *
 * Weeks 0–42 with their real dates, the ANC windows that are open in each, and
 * one week marked as now. Deliberately no "this week your baby is the size of
 * X": that copy would be invented content about a body, and this app does not
 * ship invented content — `fertility.timeline.caveat` says so in the card.
 * Native `<details>` per trimester keeps 43 rows from burying the screen.
 */
function Timeline({ lmpDate }: { lmpDate: string }) {
  const { t, locale } = useI18n()
  const tl = pregnancyTimeline(lmpDate)

  return (
    <Card title={t('fertility.timeline.title')} icon="calendar" hint={t('fertility.timeline.hint')}>
      <div className="stack stack--tight">
        {tl.currentWeek === null && <p className="card__hint">{t('fertility.timeline.noNow')}</p>}

        {([1, 2, 3] as const).map((n) => {
          const weeks = tl.weeks.filter((w) => w.trimester === n)
          return (
            <details key={n} className="fert-tri" open={tl.currentTrimester === n}>
              <summary>
                <strong>{t('fertility.timeline.trimester', { n })}</strong>{' '}
                <span className="card__hint">{t('fertility.timeline.count', { n: weeks.length })}</span>
              </summary>
              <ul className="list">
                {weeks.map((w) => (
                  <li key={w.week} className={`list__item fert-week fert-week--${w.state}`}>
                    <Icon name={WEEK_ICON[w.state]} size={18} />
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{t('fertility.timeline.week', { n: w.week })}</strong>
                      <span className="card__hint">
                        {t('fertility.timeline.range', {
                          from: fmtDate(w.fromDate, 'd MMM', locale),
                          to: fmtDate(w.toDate, 'd MMM', locale),
                        })}
                      </span>
                      {(w.state === 'now' || w.isDueWeek || w.ancSlotIds.length > 0) && (
                        <span className="row" style={{ gap: 'var(--space-2)', flexWrap: 'wrap' }}>
                          {w.state === 'now' && (
                            <span className="chip chip--mint">{t('fertility.timeline.now')}</span>
                          )}
                          {w.isDueWeek && (
                            <span className="chip chip--lavender">{t('fertility.timeline.due')}</span>
                          )}
                          {w.ancSlotIds.map((id) => (
                            <span key={id} className="chip">
                              {t(`fertility.anc.name.${id}`)}
                            </span>
                          ))}
                        </span>
                      )}
                    </span>
                  </li>
                ))}
              </ul>
            </details>
          )
        })}

        <p className="disclaimer">{t('fertility.timeline.caveat')}</p>
      </div>
    </Card>
  )
}

// ---------------------------------------------------------------------------

const STATE_ICON: Record<ReturnType<typeof ancSlotState>, IconName> = {
  done: 'check',
  upcoming: 'calendar',
  dueNow: 'health',
  passed: 'info',
}

function Anc({ me, slots, visits }: { me: string; slots: AncSlot[]; visits: Of<'fert_anc'>[] }) {
  const { t, locale } = useI18n()
  const [open, setOpen] = useState<AncSlot | null>(null)
  const progress = ancProgress(visits)
  const visitFor = (id: AncSlotId) => visits.find((v) => v.slotId === id)

  return (
    <>
      <Card title={t('fertility.anc.title')} icon="calendar" hint={t('fertility.anc.hint')}>
        <div className="stack stack--tight">
          <p>
            <strong>
              {t('fertility.anc.count', {
                done: progress.doneCount,
                total: progress.total,
                doctor: progress.doctorDone,
                doctorMin: progress.doctorMin,
              })}
            </strong>
          </p>
          <p className="card__hint">{t(progress.messageKey)}</p>

          <ul className="list">
            {slots.map((s) => {
              const visit = visitFor(s.id)
              const state = ancSlotState(s, !!visit)
              return (
                <li key={s.id} className="list__item">
                  <Icon name={STATE_ICON[state]} size={18} />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>
                      {t(`fertility.anc.name.${s.id}`)} · {t('fertility.anc.trimester', { n: s.trimester })}
                    </strong>
                    <span className="card__hint">
                      {t('fertility.anc.weeks', { from: s.fromWeek, to: s.toWeek })} ·{' '}
                      {t('fertility.anc.range', {
                        from: fmtDate(s.fromDate, 'd MMM', locale),
                        to: fmtDate(s.toDate, 'd MMM', locale),
                      })}
                    </span>
                    <span className="row" style={{ gap: 'var(--space-2)' }}>
                      {/* Word first, chip colour second — the state is legible
                          without any colour at all. */}
                      <span className={`chip ${state === 'done' ? 'chip--mint' : state === 'dueNow' ? 'chip--yellow' : ''}`}>
                        {t(`fertility.anc.state.${state}`)}
                      </span>
                      {s.doctorRequired && (
                        <span className="chip chip--lavender">
                          <Icon name="health" size={14} />
                          {t('fertility.anc.doctor')}
                        </span>
                      )}
                    </span>
                    {visit && <VisitRecord visit={visit} />}
                  </span>
                  <button
                    className={`btn btn--sm ${visit ? 'btn--ghost' : 'btn--soft'}`}
                    onClick={() => setOpen(s)}
                  >
                    {t(visit ? 'fertility.visit.edit' : 'fertility.anc.mark')}
                  </button>
                </li>
              )
            })}
          </ul>
          <p className="disclaimer">{t('fertility.anc.caveat')}</p>
        </div>
      </Card>

      <Sheet open={open !== null} onClose={() => setOpen(null)} title={t('fertility.anc.sheet')}>
        {open && (
          <AncForm
            key={open.id}
            me={me}
            slot={open}
            visit={visitFor(open.id)}
            onClose={() => setOpen(null)}
          />
        )}
      </Sheet>
    </>
  )
}

/**
 * FE7 — what a visit recorded, read back.
 *
 * Numbers and words, both typed by the owner, echoed exactly. No trend line
 * across visits, no comparison with any norm, no colour on a reading: this app
 * is a notebook for the Buku KIA page, and a notebook does not have opinions.
 */
function VisitRecord({ visit }: { visit: Of<'fert_anc'> }) {
  const { t, locale } = useI18n()
  const measures = visit.measures ?? {}
  const state = visitRecordState(measures, visit.said)
  const name = (id: AncMeasureId) => t(`fertility.measure.${id}`)

  return (
    <>
      <span className="card__hint">
        {fmtDate(visit.date, 'd MMM yyyy', locale)}
        {visit.withDoctor ? ` · ${t('fertility.anc.withDoctor')}` : ''}
        {visit.place ? ` · ${visit.place}` : ''}
      </span>
      {filledMeasures(measures).length > 0 && (
        <span className="card__hint">
          {filledMeasures(measures)
            .map((m) => `${name(m.id)} ${m.value} ${t(`fertility.measure.${m.id}.unit`)}`)
            .join(' · ')}
        </span>
      )}
      {visit.said?.trim() && <span style={{ fontSize: 13 }}>{visit.said}</span>}
      {state.typos.length > 0 && (
        <span className="card__hint">
          {t('fertility.visit.typo', { fields: state.typos.map(name).join(', ') })}
        </span>
      )}
      {state.empty && <span className="card__hint">{t('fertility.visit.empty')}</span>}
    </>
  )
}

function AncForm({
  me,
  slot,
  visit,
  onClose,
}: {
  me: string
  slot: AncSlot
  visit: Of<'fert_anc'> | undefined
  onClose: () => void
}) {
  const { t } = useI18n()
  const [date, setDate] = useState(visit?.date ?? today())
  const [withDoctor, setWithDoctor] = useState(visit?.withDoctor ?? slot.doctorRequired)
  const [place, setPlace] = useState(visit?.place ?? '')
  const [said, setSaid] = useState(visit?.said ?? '')
  const [measures, setMeasures] = useState<Record<AncMeasureId, string>>(
    () =>
      Object.fromEntries(
        ANC_MEASURES.map((k) => [k, visit?.measures?.[k]?.toString() ?? '']),
      ) as Record<AncMeasureId, string>,
  )

  const parsed: AncMeasures = {}
  for (const k of ANC_MEASURES) {
    const v = num(measures[k])
    if (v !== undefined && Number.isFinite(v)) parsed[k] = v
  }

  return (
    <div className="stack">
      <p className="card__hint">
        {t(`fertility.anc.name.${slot.id}`)} · {t('fertility.anc.weeks', { from: slot.fromWeek, to: slot.toWeek })}
      </p>
      <Field label={t('fertility.anc.visitDate')}>
        {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
      </Field>
      <label className="row" style={{ gap: 'var(--space-3)', fontSize: 14, minHeight: 34 }}>
        <input type="checkbox" checked={withDoctor} onChange={(e) => setWithDoctor(e.target.checked)} />
        <span>{t('fertility.anc.withDoctor')}</span>
      </label>
      <Field label={t('fertility.anc.place')}>
        {(p) => (
          <input
            {...p}
            value={place}
            placeholder={t('fertility.anc.placePlaceholder')}
            onChange={(e) => setPlace(e.target.value)}
          />
        )}
      </Field>

      <p className="card__hint">
        <strong>{t('fertility.visit.measures')}</strong>
      </p>
      {ANC_MEASURES.map((k) => (
        <Field key={k} label={`${t(`fertility.measure.${k}`)} (${t(`fertility.measure.${k}.unit`)})`}>
          {(p) => (
            <input
              {...p}
              type="number"
              inputMode="decimal"
              step="any"
              value={measures[k]}
              onChange={(e) => setMeasures((c) => ({ ...c, [k]: e.target.value }))}
            />
          )}
        </Field>
      ))}

      <Field label={t('fertility.visit.note')} hint={t('fertility.visit.notePlaceholder')}>
        {(p) => <textarea {...p} value={said} onChange={(e) => setSaid(e.target.value)} />}
      </Field>

      <button
        className="btn btn--block"
        onClick={async () => {
          await saveAncVisit(me, visit, {
            slotId: slot.id,
            date,
            withDoctor,
            place: place.trim(),
            measures: parsed,
            said: said.trim(),
          })
          onClose()
        }}
      >
        {t('common.save')}
      </button>
      {visit && (
        <button
          className="btn btn--ghost btn--block"
          onClick={async () => {
            await removeFert(visit.id, me)
            onClose()
          }}
        >
          {t('fertility.anc.undo')}
        </button>
      )}
      <p className="disclaimer">{t('fertility.visit.caveat')}</p>
    </div>
  )
}

// ---------------------------------------------------------------------------

/**
 * FE8 — daily tablets, and a streak that cannot punish.
 *
 * Three deliberate choices make the streak gentle rather than a chain to
 * protect: today counts as still open, so the run does not read zero at
 * breakfast; a run that ends is described by what survives it (the total, the
 * longest run, the last thirty days) and never by the break; and a missed day
 * can be filled in afterwards, so the number is a record instead of a verdict
 * on how the last few days went.
 */
function Ttd({ me, rows }: { me: string; rows: Of<'fert_ttd'>[] }) {
  const { t } = useI18n()
  const p = ttdAdherence(rows.map((r) => r.date))
  const streak = ttdStreak(rows.map((r) => r.date))
  const todayRow = rows.find((r) => r.date === today())

  return (
    <Card title={t('fertility.ttd.title')} icon="health" hint={t('fertility.ttd.hint', { target: TTD_TARGET })}>
      <div className="stack stack--tight">
        <p>
          <strong>{t('fertility.ttd.count', { taken: p.taken, target: p.target })}</strong>{' '}
          <span className="card__hint">{t('fertility.ttd.remaining', { n: p.remaining })}</span>
        </p>
        {/* The bar is decoration; the count above is the value that is announced. */}
        <span className="goal__bar" aria-hidden="true">
          <span style={{ width: `${p.percent}%` }} />
        </span>
        <p className="card__hint">{t(p.messageKey, { target: p.target })}</p>

        <p>
          {t(streak.messageKey, { current: streak.current, total: streak.total })}
        </p>
        {streak.total > 0 && (
          <p className="card__hint">
            {t('fertility.ttd.streak.stats', { best: streak.best, last30: streak.last30 })}
          </p>
        )}

        {todayRow ? (
          <button className="btn btn--soft btn--block" onClick={() => removeFert(todayRow.id, me)}>
            <Icon name="check" size={18} /> {t('fertility.ttd.taken')} — {t('fertility.ttd.undo')}
          </button>
        ) : (
          <button className="btn btn--block" onClick={() => logTtd(me, rows, today())}>
            <Icon name="plus" size={18} /> {t('fertility.ttd.take')}
          </button>
        )}

        <Backfill me={me} rows={rows} />
        <p className="card__hint">{t('fertility.ttd.streak.gentle')}</p>
        <p className="disclaimer">{t('fertility.ttd.caveat')}</p>
      </div>
    </Card>
  )
}

/**
 * A missed day, filled in later. Without this the streak would be a thing you
 * can only lose, which is the exact shape this feature is not allowed to take.
 * Native `<details>` so it stays out of the way until it is wanted.
 */
function Backfill({ me, rows }: { me: string; rows: Of<'fert_ttd'>[] }) {
  const { t } = useI18n()
  const [date, setDate] = useState(today())
  const already = rows.some((r) => r.date === date)

  return (
    <details className="fert-tri">
      <summary>{t('fertility.ttd.back')}</summary>
      <div className="stack stack--tight">
        <Field label={t('fertility.ttd.backDate')}>
          {(p) => (
            <input
              {...p}
              type="date"
              max={today()}
              value={date}
              onChange={(e) => setDate(e.target.value)}
            />
          )}
        </Field>
        <button
          className="btn btn--soft btn--block"
          disabled={already || !date}
          onClick={() => logTtd(me, rows, date)}
        >
          {t('fertility.ttd.backSave')}
        </button>
        {already && <p className="card__hint">{t('fertility.ttd.backDone')}</p>}
      </div>
    </details>
  )
}

