function P4k({ me, rows }: { me: string; rows: Of<'fert_p4k'>[] }) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)
  const values = Object.fromEntries(rows.map((r) => [r.field, r.value])) as Partial<
    Record<P4kField, string>
  >
  const p = p4kProgress(values)

  async function save(next: Record<P4kField, string>) {
    for (const f of P4K_FIELDS) {
      const row = rows.find((r) => r.field === f)
      const value = next[f].trim()
      if (row) await patchFert(row.id, { value })
      else if (value) await addFert(me, { kind: 'fert_p4k', field: f, value })
    }
    setOpen(false)
  }

  return (
    <>
      <Card
        title={t('fertility.p4k.title')}
        icon="family"
        hint={t('fertility.p4k.hint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('fertility.p4k.edit')}
          </button>
        }
      >
        <p className="card__hint">{t('fertility.p4k.filled', { filled: p.filled, total: p.total })}</p>
        <ul className="list">
          {P4K_FIELDS.map((f) => (
            <li key={f} className="list__item">
              <Icon name={values[f]?.trim() ? 'check' : 'info'} size={18} />
              <span className="grow stack stack--tight">
                <strong style={{ fontSize: 14 }}>{t(`fertility.p4k.${f}`)}</strong>
                <span className="card__hint">{values[f]?.trim() || t('fertility.p4k.empty')}</span>
              </span>
            </li>
          ))}
        </ul>
      </Card>

      <Sheet open={open} onClose={() => setOpen(false)} title={t('fertility.p4k.sheet')}>
        {open && <P4kForm values={values} onSave={save} />}
      </Sheet>
    </>
  )
}

function P4kForm({
  values,
  onSave,
}: {
  values: Partial<Record<P4kField, string>>
  onSave: (next: Record<P4kField, string>) => void
}) {
  const { t } = useI18n()
  const [draft, setDraft] = useState<Record<P4kField, string>>(
    () => Object.fromEntries(P4K_FIELDS.map((f) => [f, values[f] ?? ''])) as Record<P4kField, string>,
  )

  return (
    <div className="stack">
      {P4K_FIELDS.map((f) => (
        <Field key={f} label={t(`fertility.p4k.${f}`)}>
          {(p) => (
            <input
              {...p}
              value={draft[f]}
              onChange={(e) => setDraft((c) => ({ ...c, [f]: e.target.value }))}
            />
          )}
        </Field>
      ))}
      <button className="btn btn--block" onClick={() => onSave(draft)}>
        {t('common.save')}
      </button>
    </div>
  )
}

