const LEVEL_ICON: Record<TriageLevel, IconName> = {
  hijau: 'check',
  kuning: 'info',
  oranye: 'health',
  merah: 'emergency',
}

/**
 * FE10 + FE11 — danger-sign triage, and the surface that reaches it in one tap.
 *
 * The picker (FE10) sorts the recognised warning signs by *how soon to get in
 * touch*, never by cause: it cannot be combined into a higher level, carries no
 * probability and no reassurance, and states out loud that the app cannot
 * diagnose. FE11 is the reaching — a button fixed above the nav (`.fert-escalate`)
 * so a red sign is two taps away, open then tick, from any scroll position
 * instead of buried at the bottom of a long screen. The fixed button and the
 * inline card open the same sheet, so there is one picker, not two.
 */
function Triage({ me, history }: { me: string; history: Of<'fert_triage'>[] }) {
  const { t, locale } = useI18n()
  const [open, setOpen] = useState(false)

  return (
    <>
      {/* Fixed, so it survives every scroll position on the pregnancy view. It
          is a shortcut into the sheet, not a second copy of the checklist. */}
      <button className="fert-escalate" onClick={() => setOpen(true)}>
        <Icon name="emergency" size={22} />
        <span className="fert-escalate__label">{t('fertility.triage.escalate')}</span>
      </button>

      <Card title={t('fertility.triage.title')} icon="emergency" hint={t('fertility.triage.hint')}>
        <div className="stack stack--tight">
          <p className="disclaimer">{t('fertility.triage.cannotDiagnose')}</p>
          <button className="btn btn--block" onClick={() => setOpen(true)}>
            <Icon name="emergency" size={18} /> {t('fertility.triage.open')}
          </button>

          <p className="card__hint">{t('fertility.triage.history')}</p>
          {history.length === 0 ? (
            <EmptyState icon="info" title={t('fertility.triage.emptyHistory')} />
          ) : (
            <ul className="list">
              {history.slice(0, 8).map((h) => (
                <li key={h.id} className="list__item">
                  <Icon name={LEVEL_ICON[h.level]} size={18} />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>
                      {t('fertility.triage.saved', {
                        date: fmtDate(h.date.slice(0, 10), 'd MMM yyyy', locale),
                        level: t(`fertility.triage.${h.level}`),
                      })}
                    </strong>
                    <span className="card__hint">
                      {h.signIds.map((s) => t(`fertility.sign.${s}`)).join(' · ')}
                    </span>
                  </span>
                  <button className="btn btn--ghost btn--sm btn--icon" onClick={() => removeFert(h.id, me)}>
                    <Icon name="close" size={16} label={t('fertility.delete')} />
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
      </Card>

      <Sheet open={open} onClose={() => setOpen(false)} title={t('fertility.triage.title')}>
        {open && <TriagePicker me={me} onSaved={() => setOpen(false)} />}
      </Sheet>
    </>
  )
}

/** The checklist itself — the one place the danger signs are ticked and saved. */
function TriagePicker({ me, onSaved }: { me: string; onSaved: () => void }) {
  const { t } = useI18n()
  const [picked, setPicked] = useState<string[]>([])
  const result = triage(picked)

  return (
    <div className="stack stack--tight">
      <p className="disclaimer">{t('fertility.triage.cannotDiagnose')}</p>

      <div className={`fert-level fert-level--${result.level}`} role="status">
        <Icon name={LEVEL_ICON[result.level]} size={20} />
        <span className="stack stack--tight">
          <strong>{t(result.headingKey)}</strong>
          <span>{t(result.actionKey)}</span>
          <span>{t('fertility.triage.level', { level: result.level })}</span>
        </span>
      </div>

      <fieldset style={{ border: 0, padding: 0, margin: 0 }}>
        <legend className="visually-hidden">{t('fertility.triage.hint')}</legend>
        <div className="fert-signs">
          {DANGER_SIGNS.map((s) => (
            <label key={s.id}>
              <input
                type="checkbox"
                checked={picked.includes(s.id)}
                onChange={() =>
                  setPicked((c) => (c.includes(s.id) ? c.filter((x) => x !== s.id) : [...c, s.id]))
                }
              />
              <span>{t(`fertility.sign.${s.id}`)}</span>
            </label>
          ))}
        </div>
      </fieldset>

      <button
        className="btn btn--block"
        disabled={picked.length === 0}
        onClick={async () => {
          await addFert(me, {
            kind: 'fert_triage',
            date: new Date().toISOString(),
            signIds: result.signIds,
            level: result.level,
          })
          setPicked([])
          onSaved()
        }}
      >
        {t('fertility.triage.save')}
      </button>
    </div>
  )
}

