/** Ticks once a second while `active`, so a running timer stays honest. */
function useTick(active: boolean): number {
  const [now, setNow] = useState(() => Date.now())
  useEffect(() => {
    if (!active) return
    setNow(Date.now())
    const h = setInterval(() => setNow(Date.now()), 1000)
    return () => clearInterval(h)
  }, [active])
  return now
}

function Kicks({ me, sessions }: { me: string; sessions: Of<'fert_kick'>[] }) {
  const { t, locale } = useI18n()
  const [startedAt, setStartedAt] = useState<number | null>(null)
  const [kicks, setKicks] = useState(0)
  const now = useTick(startedAt !== null)
  const b = kickBaseline(sessions.map((s) => ({ date: s.date, minutes: s.minutes, kicks: s.kicks })))

  const minutes = startedAt === null ? 0 : Math.max(1, Math.round((now - startedAt) / 60000))

  async function finish() {
    if (startedAt !== null && kicks > 0) {
      await addFert(me, { kind: 'fert_kick', date: today(), minutes, kicks })
    }
    setStartedAt(null)
    setKicks(0)
  }

  return (
    <Card title={t('fertility.kick.title')} icon="baby" hint={t('fertility.kick.hint')}>
      <div className="stack stack--tight">
        {startedAt === null ? (
          <button className="btn btn--block" onClick={() => { setStartedAt(Date.now()); setKicks(0) }}>
            <Icon name="plus" size={18} /> {t('fertility.kick.start')}
          </button>
        ) : (
          <>
            <p className="fert-timer">{t('fertility.kick.running', { kicks, minutes })}</p>
            <button className="btn btn--block" onClick={() => setKicks((k) => k + 1)}>
              <Icon name="check" size={18} /> {t('fertility.kick.tap')}
            </button>
            <div className="row" style={{ gap: 'var(--space-2)' }}>
              <button className="btn btn--soft grow" onClick={finish} disabled={kicks === 0}>
                {t('fertility.kick.stop')}
              </button>
              <button className="btn btn--ghost" onClick={() => { setStartedAt(null); setKicks(0) }}>
                {t('fertility.kick.cancel')}
              </button>
            </div>
          </>
        )}

        <p>{t(b.messageKey)}</p>
        {b.baselineMinutes !== null && (
          <p className="card__hint">
            {t('fertility.kick.baseline', { baseline: b.baselineMinutes, latest: b.latestMinutes ?? 0 })}
          </p>
        )}

        {sessions.length === 0 ? (
          <EmptyState icon="baby" title={t('fertility.kick.empty')} />
        ) : (
          <ul className="list">
            {[...sessions].reverse().slice(0, 6).map((s) => (
              <li key={s.id} className="list__item">
                <Icon name="baby" size={18} />
                <span className="grow" style={{ fontSize: 14 }}>
                  {t('fertility.kick.session', {
                    date: fmtDate(s.date, 'd MMM', locale),
                    kicks: s.kicks,
                    minutes: s.minutes,
                  })}
                </span>
                <button className="btn btn--ghost btn--sm btn--icon" onClick={() => removeFert(s.id, me)}>
                  <Icon name="close" size={16} label={t('fertility.delete')} />
                </button>
              </li>
            ))}
          </ul>
        )}
        <p className="disclaimer">{t('fertility.kick.caveat')}</p>
      </div>
    </Card>
  )
}

function Contractions({ me, rows }: { me: string; rows: Of<'fert_ctx'>[] }) {
  const { t } = useI18n()
  const [startedAt, setStartedAt] = useState<number | null>(null)
  const now = useTick(startedAt !== null)
  const s = contractionSummary(rows.map((r) => ({ startedAt: r.startedAt, durationSec: r.durationSec })))
  const elapsed = startedAt === null ? 0 : Math.round((now - startedAt) / 1000)

  async function stop() {
    if (startedAt === null) return
    await addFert(me, {
      kind: 'fert_ctx',
      startedAt: new Date(startedAt).toISOString(),
      durationSec: Math.max(1, Math.round((Date.now() - startedAt) / 1000)),
    })
    setStartedAt(null)
  }

  return (
    <Card title={t('fertility.ctx.title')} icon="cycle" hint={t('fertility.ctx.hint')}>
      <div className="stack stack--tight">
        {startedAt === null ? (
          <button className="btn btn--block" onClick={() => setStartedAt(Date.now())}>
            <Icon name="plus" size={18} /> {t('fertility.ctx.start')}
          </button>
        ) : (
          <>
            <p className="fert-timer">{t('fertility.ctx.running', { seconds: elapsed })}</p>
            <button className="btn btn--block" onClick={stop}>
              <Icon name="check" size={18} /> {t('fertility.ctx.stop')}
            </button>
          </>
        )}

        <p>{t(s.messageKey)}</p>
        {s.count > 0 && (
          <p className="card__hint">
            {t('fertility.ctx.stats', {
              count: s.count,
              duration: s.avgDurationSec ?? 0,
              interval: s.avgIntervalSec === null ? 0 : Math.round((s.avgIntervalSec / 60) * 10) / 10,
            })}
          </p>
        )}
        {rows.length > 0 && (
          <button
            className="btn btn--danger btn--block"
            onClick={async () => {
              for (const r of rows) await removeFert(r.id, me)
            }}
          >
            <Icon name="close" size={18} /> {t('fertility.ctx.clear')}
          </button>
        )}
        <p className="disclaimer">{t('fertility.ctx.caveat')}</p>
      </div>
    </Card>
  )
}
