import { addDays, differenceInCalendarDays, format, parseISO } from 'date-fns'
import { estimate } from '@/features/cycle/cycleMath'
import type { FertilityKey } from './messages'

/**
 * Fertility and pregnancy arithmetic (FAM-01..03).
 *
 * Everything here is arithmetic on dates and numbers the owner typed. Nothing
 * diagnoses, classifies risk, promises a pregnancy, or advises on
 * contraception. Every estimate leaves with a range and a caveat key, and every
 * outcome is a **message key**, never copy — see CLAUDE.md §i18n.
 */

const iso = (d: Date) => format(d, 'yyyy-MM-dd')

function median(ns: number[]): number {
  const s = [...ns].sort((a, b) => a - b)
  const mid = Math.floor(s.length / 2)
  return s.length % 2 ? s[mid]! : (s[mid - 1]! + s[mid]!) / 2
}

// ---------------------------------------------------------------------------
// Fertile window
// ---------------------------------------------------------------------------

/** Three buckets, and deliberately never higher than "sedang". */
export type Confidence = 'none' | 'low' | 'medium'

export interface FertileWindow {
  /** Widest plausible window, or null when there is not enough history. */
  window: [string, string] | null
  ovulation: string | null
  ovulationRange: [string, string] | null
  confidence: Confidence
  confidenceKey: FertilityKey
  basedOnCycles: number
}

const NO_WINDOW: FertileWindow = {
  window: null,
  ovulation: null,
  ovulationRange: null,
  confidence: 'none',
  confidenceKey: 'fertility.conf.none',
  basedOnCycles: 0,
}

/**
 * The luteal phase (ovulation → next period) is the steadier half of the cycle,
 * so ovulation is pinned *backwards* from the estimated next start rather than
 * forwards from the last one. Reuses `cycleMath.estimate` so the two screens can
 * never disagree about the same history.
 */
export function fertileWindow(cycleStarts: string[], today = new Date()): FertileWindow {
  const est = estimate(cycleStarts, today)
  if (est.nextStart === null) return { ...NO_WINDOW, basedOnCycles: est.basedOnCycles }

  const ov = addDays(parseISO(est.nextStart), -14)
  // Half the observed spread, floored at ±2 days: even a metronome-regular
  // history does not justify naming one certain day.
  const pad = Math.max(2, Math.ceil((est.variationDays ?? 0) / 2))

  return {
    // Sperm survive up to ~5 days and an ovum ~1, so the window opens well
    // before the estimate and closes just after it, then widens by the pad.
    window: [iso(addDays(ov, -5 - pad)), iso(addDays(ov, 1 + pad))],
    ovulation: iso(ov),
    ovulationRange: [iso(addDays(ov, -pad)), iso(addDays(ov, pad))],
    confidence: est.basedOnCycles >= 4 ? 'medium' : 'low',
    confidenceKey: est.basedOnCycles >= 4 ? 'fertility.conf.medium' : 'fertility.conf.low',
    basedOnCycles: est.basedOnCycles,
  }
}

// ---------------------------------------------------------------------------
// Period outlook — the only estimate the non-conception modes get
// ---------------------------------------------------------------------------

export interface PeriodOutlook {
  /**
   * Plausible window for the next period start. There is deliberately no single
   * `nextStart` field: a bare date would be read as a promise, and in "cegah"
   * mode it would be read as contraception. Only the range leaves this module.
   */
  range: [string, string] | null
  averageLength: number | null
  variationDays: number | null
  confidence: Confidence
  confidenceKey: FertilityKey
  basedOnCycles: number
}

/**
 * Same history, same estimator as the cycle screen — `cycleMath.estimate` — with
 * the point estimate dropped and the confidence mapped onto this module's keys.
 */
export function periodOutlook(cycleStarts: string[], today = new Date()): PeriodOutlook {
  const est = estimate(cycleStarts, today)
  const confidence: Confidence =
    est.nextStartRange === null ? 'none' : est.basedOnCycles >= 4 ? 'medium' : 'low'

  return {
    range: est.nextStartRange,
    averageLength: est.averageLength,
    variationDays: est.variationDays,
    confidence,
    confidenceKey: `fertility.conf.${confidence}` as FertilityKey,
    basedOnCycles: est.basedOnCycles,
  }
}

// ---------------------------------------------------------------------------
// Postpartum — the KF visit windows
// ---------------------------------------------------------------------------

export type KfSlotId = 'KF1' | 'KF2' | 'KF3' | 'KF4'

export interface KfSlotSpec {
  id: KfSlotId
  fromDay: number
  toDay: number
}

/**
 * Four postpartum contacts in the first 42 days, the spacing the Buku KIA uses:
 * KF1 in the first two days, KF2 on days 3–7, KF3 on days 8–28, KF4 on days
 * 29–42. Day 0 is the day of birth.
 *
 * DOCUMENTED GAP: this is the programme's own spacing, transcribed from the Buku
 * KIA schedule and nothing more. It is not a clinical plan, the app cites no
 * clinic and names no practitioner, and the bidan or dokter sets the real dates
 * — the UI says exactly that. Same treatment as `ANC_SLOTS`.
 */
export const KF_SLOTS: readonly KfSlotSpec[] = [
  { id: 'KF1', fromDay: 0, toDay: 2 },
  { id: 'KF2', fromDay: 3, toDay: 7 },
  { id: 'KF3', fromDay: 8, toDay: 28 },
  { id: 'KF4', fromDay: 29, toDay: 42 },
]

export const KF_TOTAL = KF_SLOTS.length

export interface KfSlot extends KfSlotSpec {
  fromDate: string
  toDate: string
}

export function postpartumSchedule(birthDate: string): KfSlot[] {
  const born = parseISO(birthDate)
  return KF_SLOTS.map((s) => ({
    ...s,
    fromDate: iso(addDays(born, s.fromDay)),
    toDate: iso(addDays(born, s.toDay)),
  }))
}

/** Days since birth. Day of birth is 0; a future date reads negative. */
export function postpartumDay(birthDate: string, today = new Date()): number {
  return differenceInCalendarDays(today, parseISO(birthDate))
}

export interface PostpartumProgress {
  day: number
  doneCount: number
  total: number
  /** Day 42 is the end of the KF window, not the end of recovery. */
  withinWindow: boolean
  messageKey: FertilityKey
}

export function postpartumProgress(
  birthDate: string,
  doneSlotIds: readonly string[],
  today = new Date(),
): PostpartumProgress {
  const day = postpartumDay(birthDate, today)
  const doneCount = new Set(KF_SLOTS.filter((s) => doneSlotIds.includes(s.id)).map((s) => s.id)).size

  return {
    day,
    doneCount,
    total: KF_TOTAL,
    withinWindow: day >= 0 && day <= 42,
    messageKey:
      doneCount >= KF_TOTAL
        ? 'fertility.pp.sum.all'
        : doneCount === 0
          ? 'fertility.pp.sum.none'
          : 'fertility.pp.sum.some',
  }
}

// ---------------------------------------------------------------------------
// DPO and the two-week wait
// ---------------------------------------------------------------------------

export interface Wait {
  /** Days past ovulation. Negative before the estimated ovulation day. */
  dpo: number
  /** Earliest date a test is worth doing, per the same estimate. */
  testFrom: string
  canTestNow: boolean
  statusKey: FertilityKey
}

export function twoWeekWait(ovulationDate: string, today = new Date()): Wait {
  const ov = parseISO(ovulationDate)
  const dpo = differenceInCalendarDays(today, ov)
  // 14 DPO, not 10 or 12: an early negative sends people back to test again, and
  // this app should not manufacture that particular disappointment.
  const testFrom = addDays(ov, 14)
  const statusKey: FertilityKey =
    dpo < 0
      ? 'fertility.tww.notYet'
      : dpo <= 6
        ? 'fertility.tww.early'
        : dpo <= 13
          ? 'fertility.tww.waiting'
          : dpo <= 20
            ? 'fertility.tww.testWindow'
            : 'fertility.tww.overdue'

  return { dpo, testFrom: iso(testFrom), canTestNow: dpo >= 14, statusKey }
}

// ---------------------------------------------------------------------------
// Basal body temperature
// ---------------------------------------------------------------------------

export interface BbtPoint {
  date: string
  celsius: number
}

export interface BbtRead {
  points: BbtPoint[]
  min: number | null
  max: number | null
  /** First day of a *possible* sustained rise. Never presented as proof. */
  shiftDate: string | null
  messageKey: FertilityKey
}

const BBT_MIN_POINTS = 10

/**
 * Looks for the classic three-over-six pattern: three readings in a row above
 * the highest of the previous six, by at least 0.2 °C. It is a pattern in the
 * numbers the owner wrote down — the app says "mungkin", and stops there.
 */
export function bbtRead(raw: BbtPoint[]): BbtRead {
  const byDate = new Map(raw.map((p) => [p.date, p]))
  const points = [...byDate.values()].sort((a, b) => a.date.localeCompare(b.date))
  if (points.length === 0) {
    return { points, min: null, max: null, shiftDate: null, messageKey: 'fertility.bbt.needMore' }
  }

  const temps = points.map((p) => p.celsius)
  let shiftDate: string | null = null
  for (let i = 6; i + 2 < points.length; i++) {
    const priorHigh = Math.max(...temps.slice(i - 6, i))
    if (temps.slice(i, i + 3).every((t) => t >= priorHigh + 0.2)) {
      shiftDate = points[i]!.date
      break
    }
  }

  return {
    points,
    min: Math.min(...temps),
    max: Math.max(...temps),
    shiftDate,
    messageKey:
      points.length < BBT_MIN_POINTS
        ? 'fertility.bbt.needMore'
        : shiftDate
          ? 'fertility.bbt.shiftMaybe'
          : 'fertility.bbt.noShift',
  }
}

