// ---------------------------------------------------------------------------
// ANC — Indonesia's K6 minimum
// ---------------------------------------------------------------------------

export type AncSlotId = 'K1' | 'K2' | 'K3' | 'K4' | 'K5' | 'K6'

export interface AncSlotSpec {
  id: AncSlotId
  trimester: 1 | 2 | 3
  fromWeek: number
  toWeek: number
  /** K6 asks for at least two contacts with a dokter; these are those two. */
  doctorRequired: boolean
}

/**
 * K6: one contact in trimester 1, two in trimester 2, three in trimester 3, of
 * which at least two are with a dokter.
 *
 * Trimester boundaries follow the Buku KIA convention (TM1 ≤12 w, TM2 13–24 w,
 * TM3 ≥25 w), which is *not* the 14/28 split `pregnancyMath.dating()` uses for
 * the generic week counter. Both are correct in their own context; do not
 * "fix" one to match the other.
 *
 * The week bands inside each trimester are a spacing suggestion so the six
 * contacts do not bunch up. They are not a clinical schedule — the bidan or
 * dokter sets the real dates, and the UI says exactly that.
 */
export const ANC_SLOTS: readonly AncSlotSpec[] = [
  { id: 'K1', trimester: 1, fromWeek: 6, toWeek: 12, doctorRequired: true },
  { id: 'K2', trimester: 2, fromWeek: 13, toWeek: 18, doctorRequired: false },
  { id: 'K3', trimester: 2, fromWeek: 19, toWeek: 24, doctorRequired: false },
  { id: 'K4', trimester: 3, fromWeek: 25, toWeek: 30, doctorRequired: false },
  { id: 'K5', trimester: 3, fromWeek: 31, toWeek: 36, doctorRequired: true },
  { id: 'K6', trimester: 3, fromWeek: 37, toWeek: 40, doctorRequired: false },
]

export const ANC_TOTAL = ANC_SLOTS.length
export const ANC_DOCTOR_MIN = ANC_SLOTS.filter((s) => s.doctorRequired).length

export interface AncSlot extends AncSlotSpec {
  fromDate: string
  toDate: string
}

export function ancSchedule(lmpDate: string): AncSlot[] {
  const lmp = parseISO(lmpDate)
  return ANC_SLOTS.map((s) => ({
    ...s,
    fromDate: iso(addDays(lmp, s.fromWeek * 7)),
    // Inclusive of the whole closing week, so K6 covers 37w0d..40w6d.
    toDate: iso(addDays(lmp, s.toWeek * 7 + 6)),
  }))
}

export type AncState = 'done' | 'upcoming' | 'dueNow' | 'passed'

/** Structural on purpose: the KF postpartum slots below use the same states. */
export function ancSlotState(
  slot: { fromDate: string; toDate: string },
  done: boolean,
  today = new Date(),
): AncState {
  if (done) return 'done'
  const t = iso(today)
  if (t < slot.fromDate) return 'upcoming'
  if (t > slot.toDate) return 'passed'
  return 'dueNow'
}

export interface AncVisitRecord {
  slotId: AncSlotId
  withDoctor: boolean
}

export interface AncProgress {
  doneCount: number
  total: number
  doctorDone: number
  doctorMin: number
  meetsMinimum: boolean
  messageKey: FertilityKey
}

/** Counts what was logged against the K6 minimum. A count, never a grade. */
export function ancProgress(visits: AncVisitRecord[]): AncProgress {
  const slots = new Set(visits.map((v) => v.slotId))
  const doneCount = slots.size
  const doctorDone = new Set(visits.filter((v) => v.withDoctor).map((v) => v.slotId)).size
  const meetsMinimum = doneCount >= ANC_TOTAL && doctorDone >= ANC_DOCTOR_MIN

  return {
    doneCount,
    total: ANC_TOTAL,
    doctorDone,
    doctorMin: ANC_DOCTOR_MIN,
    meetsMinimum,
    messageKey: meetsMinimum
      ? 'fertility.anc.sum.all'
      : doneCount === 0
        ? 'fertility.anc.sum.none'
        : doctorDone < ANC_DOCTOR_MIN
          ? 'fertility.anc.sum.needDoctor'
          : 'fertility.anc.sum.some',
  }
}

// ---------------------------------------------------------------------------
// Tablet Tambah Darah
// ---------------------------------------------------------------------------

/** The programme's own target: 90 tablets across the pregnancy. */
export const TTD_TARGET = 90

export interface TtdProgress {
  taken: number
  target: number
  remaining: number
  percent: number
  messageKey: FertilityKey
}

export function ttdAdherence(dates: string[], target = TTD_TARGET): TtdProgress {
  // One tablet a day: two entries for the same date are a double tap, not a
  // second tablet, so they must not inflate the count toward 90.
  const taken = new Set(dates).size
  return {
    taken,
    target,
    remaining: Math.max(0, target - taken),
    percent: target > 0 ? Math.min(100, Math.round((taken / target) * 100)) : 0,
    messageKey:
      taken === 0
        ? 'fertility.ttd.none'
        : taken >= target
          ? 'fertility.ttd.done'
          : 'fertility.ttd.progress',
  }
}

// ---------------------------------------------------------------------------
// P4K — Program Perencanaan Persalinan dan Pencegahan Komplikasi
// ---------------------------------------------------------------------------

export const P4K_FIELDS = [
  'tempat',
  'penolong',
  'pendamping',
  'transportasi',
  'donorDarah',
  'dana',
  'dokumen',
] as const
export type P4kField = (typeof P4K_FIELDS)[number]

export interface P4kProgress {
  filled: number
  total: number
  missing: P4kField[]
}

export function p4kProgress(values: Partial<Record<P4kField, string>>): P4kProgress {
  const missing = P4K_FIELDS.filter((f) => !values[f]?.trim())
  return { filled: P4K_FIELDS.length - missing.length, total: P4K_FIELDS.length, missing }
}

// ---------------------------------------------------------------------------
// Danger-sign triage
// ---------------------------------------------------------------------------

export type TriageLevel = 'hijau' | 'kuning' | 'oranye' | 'merah'

export interface DangerSign {
  id: string
  level: Exclude<TriageLevel, 'hijau'>
}

/**
 * The tanda bahaya list from the Buku KIA, grouped by how soon to get in touch.
 * The grouping answers "when do I call?", never "what is wrong?" — this module
 * has no opinion about a cause and the UI states that it cannot have one.
 */
export const DANGER_SIGNS = [
  { id: 'perdarahanBanyak', level: 'merah' },
  { id: 'kejang', level: 'merah' },
  { id: 'ketubanPecah', level: 'merah' },
  { id: 'gerakJaninBerkurang', level: 'merah' },
  { id: 'sakitKepalaHebat', level: 'merah' },
  { id: 'sesakBerat', level: 'merah' },
  { id: 'flek', level: 'oranye' },
  { id: 'nyeriPerutMenetap', level: 'oranye' },
  { id: 'bengkakMendadak', level: 'oranye' },
  { id: 'demam', level: 'oranye' },
  { id: 'muntahTerus', level: 'oranye' },
  { id: 'nyeriBak', level: 'oranye' },
  { id: 'pusingRingan', level: 'kuning' },
  { id: 'bengkakSore', level: 'kuning' },
  { id: 'kontraksiJarang', level: 'kuning' },
  { id: 'sembelit', level: 'kuning' },
] as const satisfies readonly DangerSign[]

/** Kept as a literal union so `fertility.sign.<id>` resolves to a real key. */
export type DangerSignId = (typeof DANGER_SIGNS)[number]['id']

const LEVEL_ORDER: TriageLevel[] = ['hijau', 'kuning', 'oranye', 'merah']

export interface TriageResult {
  level: TriageLevel
  headingKey: FertilityKey
  actionKey: FertilityKey
  /** Only the ids that were recognised, in list order. */
  signIds: DangerSignId[]
}

/**
 * Highest selected level wins — and only that. Combining two amber signs into a
 * red one would be risk classification, which this app must not do.
 */
export function triage(selected: readonly string[]): TriageResult {
  const chosen = new Set(selected)
  const signIds = DANGER_SIGNS.filter((s) => chosen.has(s.id)).map((s) => s.id)
  const level = DANGER_SIGNS.filter((s) => chosen.has(s.id)).reduce<TriageLevel>(
    (top, s) => (LEVEL_ORDER.indexOf(s.level) > LEVEL_ORDER.indexOf(top) ? s.level : top),
    'hijau',
  )
  return {
    level,
    headingKey: `fertility.triage.${level}` as FertilityKey,
    actionKey: `fertility.triage.${level}.action` as FertilityKey,
    signIds,
  }
}

// ---------------------------------------------------------------------------
// Kick counter
// ---------------------------------------------------------------------------

export interface KickSession {
  date: string
  minutes: number
  kicks: number
}

export interface KickBaseline {
  /** Median minutes-per-10-movements across earlier sessions, this person only. */
  baselineMinutes: number | null
  latestMinutes: number | null
  deltaMinutes: number | null
  basedOnSessions: number
  messageKey: FertilityKey
}

const KICK_MIN_SESSIONS = 3

/**
 * Compares the latest session with the person's own median, normalised to
 * minutes per ten movements. There is no population norm here and no "baby is
 * fine" verdict — only "this looks like your usual" or "this looks different".
 * Median rather than mean, so one restless afternoon does not move the baseline.
 */
export function kickBaseline(sessions: KickSession[]): KickBaseline {
  const usable = sessions
    .filter((s) => s.kicks > 0 && s.minutes > 0)
    .sort((a, b) => a.date.localeCompare(b.date))
  const rate = (s: KickSession) => (s.minutes / s.kicks) * 10

  const latest = usable.at(-1)
  const prior = usable.slice(0, -1)
  if (!latest || prior.length < KICK_MIN_SESSIONS) {
    return {
      baselineMinutes: null,
      latestMinutes: latest ? Math.round(rate(latest)) : null,
      deltaMinutes: null,
      basedOnSessions: prior.length,
      messageKey: 'fertility.kick.needBaseline',
    }
  }

  const baseline = median(prior.map(rate))
  const latestRate = rate(latest)
  const messageKey: FertilityKey =
    latestRate > baseline * 1.5
      ? 'fertility.kick.slower'
      : latestRate < baseline * 0.5
        ? 'fertility.kick.faster'
        : 'fertility.kick.similar'

  return {
    baselineMinutes: Math.round(baseline),
    latestMinutes: Math.round(latestRate),
    deltaMinutes: Math.round(latestRate - baseline),
    basedOnSessions: prior.length,
    messageKey,
  }
}

// ---------------------------------------------------------------------------
// Contraction timer
// ---------------------------------------------------------------------------

export interface Contraction {
  startedAt: string
  durationSec: number
}

export interface ContractionSummary {
  count: number
  avgDurationSec: number | null
  avgIntervalSec: number | null
  regular: boolean
  messageKey: FertilityKey
}

const CTX_MIN = 4

/** Describes the pattern the owner recorded. It never says labour has started. */
export function contractionSummary(list: Contraction[]): ContractionSummary {
  const sorted = [...list].sort((a, b) => a.startedAt.localeCompare(b.startedAt))
  if (sorted.length === 0) {
    return {
      count: 0,
      avgDurationSec: null,
      avgIntervalSec: null,
      regular: false,
      messageKey: 'fertility.ctx.none',
    }
  }

  const gaps: number[] = []
  for (let i = 1; i < sorted.length; i++) {
    const g =
      (Date.parse(sorted[i]!.startedAt) - Date.parse(sorted[i - 1]!.startedAt)) / 1000
    // Drop a gap that spans a break in timing; those are two sessions, not one.
    if (g > 0 && g <= 60 * 60) gaps.push(g)
  }

  const mean = (ns: number[]) => ns.reduce((s, n) => s + n, 0) / ns.length
  const avgInterval = gaps.length ? mean(gaps) : null
  // "Teratur" only describes the spacing of what was logged: every gap within
  // ±20% of their mean, over enough contractions for that to mean anything.
  const regular =
    sorted.length >= CTX_MIN &&
    avgInterval !== null &&
    gaps.every((g) => Math.abs(g - avgInterval) <= avgInterval * 0.2)

  return {
    count: sorted.length,
    avgDurationSec: Math.round(mean(sorted.map((c) => c.durationSec))),
    avgIntervalSec: avgInterval === null ? null : Math.round(avgInterval),
    regular,
    messageKey:
      sorted.length < CTX_MIN
        ? 'fertility.ctx.needMore'
        : regular
          ? 'fertility.ctx.regular'
          : 'fertility.ctx.irregular',
  }
}
