import { addDays, differenceInCalendarDays, format, parseISO } from 'date-fns'
import { ANC_SLOTS, type AncSlotId } from './fertilityMath'
import type { FertilityKey } from './messages'

/**
 * The pregnancy half of the module: what week it is and *why* we think so
 * (FE5), what the six antenatal contacts recorded (FE7), and how the tablet
 * count is described without turning a missed day into a punishment (FE8).
 *
 * Same house rules as `fertilityMath.ts`: arithmetic on values the owner typed,
 * message keys instead of copy, no diagnosis, no norm, no verdict. Nothing here
 * decides whether a measurement is healthy — the widest checks in this file
 * catch a slipped decimal point, and say so in those words.
 */

const iso = (d: Date) => format(d, 'yyyy-MM-dd')

// ---------------------------------------------------------------------------
// FE5 — the assumption behind every week number
// ---------------------------------------------------------------------------

/** Where the week count comes from. Always shown, always editable. */
export type DatingBasis = 'lmp' | 'usg'

export interface DatingAssumption {
  basis: DatingBasis
  /** First day of the last period, as typed on the pregnancy record. */
  lmpDate: string
  /** Date of the dating scan and the age the scan reported, as read off it. */
  usgDate?: string
  usgWeeks?: number
  usgDays?: number
}

export interface DatingSource {
  basis: DatingBasis
  /** The LMP-equivalent date every downstream calculation runs on. */
  lmpDate: string
  labelKey: FertilityKey
  /**
   * Scan-derived start minus typed start, in days — positive when the scan puts
   * the pregnancy *earlier* along than the period date does. Null unless both
   * are known. It is a difference between two numbers the owner supplied, not a
   * correction of one by the other: the app has no opinion on which is right.
   */
  shiftDays: number | null
  /** The chosen basis was unusable, so the typed LMP was used instead. */
  fellBack: boolean
}

const MAX_WEEKS = 42

/** A scan is usable only if it carries a date and an age that can exist. */
export function usgLmp(a: DatingAssumption): string | null {
  const { usgDate, usgWeeks, usgDays = 0 } = a
  if (!usgDate || usgWeeks === undefined) return null
  if (!Number.isInteger(usgWeeks) || usgWeeks < 0 || usgWeeks > MAX_WEEKS) return null
  if (!Number.isInteger(usgDays) || usgDays < 0 || usgDays > 6) return null
  const scan = parseISO(usgDate)
  if (Number.isNaN(scan.getTime())) return null
  return iso(addDays(scan, -(usgWeeks * 7 + usgDays)))
}

/**
 * Resolves the assumption into one date. A scan the owner has not finished
 * entering silently falls back to the period date rather than throwing the
 * screen away — but `fellBack` is returned so the card can say which one it
 * actually used, instead of showing "USG" over a number derived from the LMP.
 */
export function resolveDating(a: DatingAssumption): DatingSource {
  const fromScan = usgLmp(a)
  const shiftDays =
    fromScan === null ? null : differenceInCalendarDays(parseISO(a.lmpDate), parseISO(fromScan))
  const useScan = a.basis === 'usg' && fromScan !== null

  return {
    basis: useScan ? 'usg' : 'lmp',
    lmpDate: useScan ? fromScan : a.lmpDate,
    labelKey: useScan ? 'fertility.dating.fromUsg' : 'fertility.dating.fromLmp',
    shiftDays,
    fellBack: a.basis === 'usg' && !useScan,
  }
}

// ---------------------------------------------------------------------------
// FE5 — the week-by-week timeline
// ---------------------------------------------------------------------------

export type WeekState = 'past' | 'now' | 'ahead'

export interface TimelineWeek {
  /** Completed weeks since the assumed start: week 0 is the first seven days. */
  week: number
  fromDate: string
  toDate: string
  trimester: 1 | 2 | 3
  state: WeekState
  /** ANC contacts whose window is open during this week. */
  ancSlotIds: AncSlotId[]
  /** Week 40 — where the 280-day estimate lands. Not a date, a week. */
  isDueWeek: boolean
}

export interface Timeline {
  weeks: TimelineWeek[]
  /** Null before the start date or past week 42 — "ask, don't compute". */
  currentWeek: number | null
  currentTrimester: 1 | 2 | 3 | null
}

/**
 * Trimester bands follow the Buku KIA convention (TM1 ≤12 w, TM2 13–24 w, TM3
 * ≥25 w) so the group headings agree with `ANC_SLOTS`. `pregnancyMath.dating()`
 * splits at 14/28 for the generic counter; both are right in their own context
 * and neither should be "fixed" to match the other.
 */
export const trimesterOf = (week: number): 1 | 2 | 3 => (week <= 12 ? 1 : week <= 24 ? 2 : 3)

export const DUE_WEEK = 40

export function pregnancyTimeline(lmpDate: string, today = new Date()): Timeline {
  const lmp = parseISO(lmpDate)
  const elapsed = differenceInCalendarDays(today, lmp)
  const nowWeek = Math.floor(elapsed / 7)
  const currentWeek = elapsed < 0 || nowWeek > MAX_WEEKS ? null : nowWeek

  const weeks: TimelineWeek[] = []
  for (let w = 0; w <= MAX_WEEKS; w++) {
    weeks.push({
      week: w,
      fromDate: iso(addDays(lmp, w * 7)),
      toDate: iso(addDays(lmp, w * 7 + 6)),
      trimester: trimesterOf(w),
      state: currentWeek === null ? 'ahead' : w < currentWeek ? 'past' : w === currentWeek ? 'now' : 'ahead',
      ancSlotIds: ANC_SLOTS.filter((s) => w >= s.fromWeek && w <= s.toWeek).map((s) => s.id),
      isDueWeek: w === DUE_WEEK,
    })
  }

  return {
    weeks,
    currentWeek,
    currentTrimester: currentWeek === null ? null : trimesterOf(currentWeek),
  }
}

// ---------------------------------------------------------------------------
// FE7 — what a visit recorded
// ---------------------------------------------------------------------------

/**
 * The measurements a Buku KIA page has a box for. Every one is typed in by the
 * owner from what they were told; the app measures nothing and reads nothing
 * from a device.
 */
export const ANC_MEASURES = [
  'beratKg',
  'sistol',
  'diastol',
  'lilaCm',
  'tfuCm',
  'djjBpm',
  'hbGdl',
] as const
export type AncMeasureId = (typeof ANC_MEASURES)[number]
export type AncMeasures = Partial<Record<AncMeasureId, number>>

/**
 * Deliberately absurd outer bounds. These are **not** normal ranges and must
 * never be narrowed into any: a reading outside them is a typo — a weight in
 * grams, a decimal point in the wrong place — and the copy says exactly that.
 * Judging whether a real reading is fine is a bidan's job, not this file's.
 */
const TYPO_BOUNDS: Record<AncMeasureId, [number, number]> = {
  beratKg: [20, 250],
  sistol: [40, 300],
  diastol: [20, 200],
  lilaCm: [8, 70],
  tfuCm: [3, 70],
  djjBpm: [20, 300],
  hbGdl: [1, 30],
}

/** Filled measurements in a fixed order, so two visits read the same way. */
export function filledMeasures(m: AncMeasures): { id: AncMeasureId; value: number }[] {
  return ANC_MEASURES.filter((k) => typeof m[k] === 'number' && Number.isFinite(m[k])).map((k) => ({
    id: k,
    value: m[k] as number,
  }))
}

/** Ids whose value cannot be a reading at all. A spell-check, not a screening. */
export function measureTypos(m: AncMeasures): AncMeasureId[] {
  return filledMeasures(m)
    .filter(({ id, value }) => value < TYPO_BOUNDS[id][0] || value > TYPO_BOUNDS[id][1])
    .map(({ id }) => id)
}

export interface VisitRecordState {
  measuredCount: number
  hasNote: boolean
  /** Nothing beyond the date was written down yet. */
  empty: boolean
  typos: AncMeasureId[]
  messageKey: FertilityKey
}

/** Describes one visit's record. Counts what is written; never grades it. */
export function visitRecordState(m: AncMeasures, note?: string): VisitRecordState {
  const measuredCount = filledMeasures(m).length
  const hasNote = !!note?.trim()
  const typos = measureTypos(m)

  return {
    measuredCount,
    hasNote,
    empty: measuredCount === 0 && !hasNote,
    typos,
    messageKey: typos.length
      ? 'fertility.visit.typo'
      : measuredCount === 0 && !hasNote
        ? 'fertility.visit.empty'
        : 'fertility.visit.some',
  }
}

// ---------------------------------------------------------------------------
// FE8 — the gentle streak
// ---------------------------------------------------------------------------

export interface TtdStreak {
  /** Consecutive days up to today. Today counts as still open, never as a miss. */
  current: number
  /** Longest run ever logged. Only ever goes up. */
  best: number
  /** Days logged in the last 30, so a broken run still has something to show. */
  last30: number
  total: number
  messageKey: FertilityKey
}

/**
 * The non-punishing part is the anchor. A run is counted backwards from
 * yesterday when today has not been logged yet, so the number does not drop to
 * zero at midnight for someone who takes their tablet after dinner — and the
 * copy for a run that has ended (`fertility.ttd.streak.paused`) mentions the
 * total, never the break. There is no penalty, no reset ceremony, and `best` is
 * kept forever, because the point of the count is the 90 tablets and not the
 * chain.
 */
export function ttdStreak(dates: readonly string[], today = new Date()): TtdStreak {
  const set = new Set(dates)
  const has = (d: Date) => set.has(iso(d))

  let best = 0
  for (const d of set) {
    // Count each run once, from its first day.
    if (has(addDays(parseISO(d), -1))) continue
    let run = 1
    while (has(addDays(parseISO(d), run))) run++
    best = Math.max(best, run)
  }

  const anchor = has(today) ? today : has(addDays(today, -1)) ? addDays(today, -1) : null
  let current = 0
  if (anchor) {
    while (has(addDays(anchor, -current))) current++
  }

  const from = addDays(today, -29)
  const last30 = [...set].filter((d) => d >= iso(from) && d <= iso(today)).length

  return {
    current,
    best,
    last30,
    total: set.size,
    messageKey:
      set.size === 0
        ? 'fertility.ttd.streak.none'
        : current === 0
          ? 'fertility.ttd.streak.paused'
          : 'fertility.ttd.streak.going',
  }
}
