import { useState } from 'react'
import { Link } from 'react-router-dom'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useOwned } from '@/db/hooks'
import type { CycleLog } from '@/types/domain'
import { useI18n, type MessageKey } from '@/i18n'
import { fmtDate } from '@/i18n/format'
import {
  MUCUS_TYPES,
  OPK_RESULTS,
  PRECONCEPTION_ITEMS,
  SUGGESTED_QUESTIONS,
  bbtRead,
  fertileWindow,
  twoWeekWait,
  type BbtRead,
  type Mucus,
  type Opk,
  type PreconceptionItem,
} from './fertilityMath'
import { addFert, patchFert, removeFert, saveDay, type FertilityData, type Of } from './store'

const today = () => format(new Date(), 'yyyy-MM-dd')

/**
 * Program hamil.
 *
 * The fertile window comes from the cycle module's own logs and its own
 * estimator, so this screen and `/siklus` can never disagree. Nothing here
 * promises a result, and none of it is usable as contraception — the caveat
 * says so in both languages.
 */
export default function Trying({ me, data }: { me: string; data: FertilityData }) {
  const { t, locale } = useI18n()
  const [sheetDate, setSheetDate] = useState<string | null>(null)

  const cycles = useOwned<CycleLog>('cycles', me)
  const win = fertileWindow((cycles ?? []).map((c) => c.startDate))
  const bbt = bbtRead(
    data.days.flatMap((d) => (d.bbtC === undefined ? [] : [{ date: d.date, celsius: d.bbtC }])),
  )
  const wait = win.ovulation ? twoWeekWait(win.ovulation) : null
  const editing = sheetDate ? data.days.find((d) => d.date === sheetDate) : undefined

  return (
    <>
      <Card title={t('fertility.window.title')} icon="cycle">
        {win.window === null ? (
          <EmptyState
            icon="cycle"
            title={t('fertility.window.none')}
            hint={t('fertility.window.noneHint')}
            action={
              <Link to="/siklus" className="btn btn--soft btn--sm">
                <Icon name="cycle" size={16} /> {t('fertility.window.openCycle')}
              </Link>
            }
          />
        ) : (
          <div className="stack stack--tight">
            <p>
              <strong>
                {t('fertility.window.range', {
                  from: fmtDate(win.window[0], 'd MMM', locale),
                  to: fmtDate(win.window[1], 'd MMM yyyy', locale),
                })}
              </strong>
            </p>
            <p className="card__hint">
              {t('fertility.window.ovulation', {
                from: fmtDate(win.ovulationRange![0], 'd MMM', locale),
                to: fmtDate(win.ovulationRange![1], 'd MMM', locale),
              })}
            </p>
            <p className="card__hint">
              {t('fertility.window.based', {
                n: win.basedOnCycles,
                confidence: t(win.confidenceKey),
              })}
            </p>
            <p className="disclaimer">{t('fertility.window.caveat')}</p>
          </div>
        )}
      </Card>

      {wait && (
        <Card title={t('fertility.dpo.title')} icon="calendar">
          <div className="stack stack--tight">
            <p>
              <strong>
                {wait.dpo >= 0
                  ? t('fertility.dpo.value', { n: wait.dpo })
                  : t('fertility.dpo.before', { n: -wait.dpo })}
              </strong>
            </p>
            <p>{t(wait.statusKey)}</p>
            <p className="card__hint">
              {t('fertility.dpo.testFrom', { date: fmtDate(wait.testFrom, 'd MMM yyyy', locale) })}
            </p>
            <p className="disclaimer">{t('fertility.tww.caveat')}</p>
          </div>
        </Card>
      )}

      <Card
        title={t('fertility.log.title')}
        icon="health"
        action={
          <button className="btn btn--sm" onClick={() => setSheetDate(today())}>
            <Icon name="plus" size={16} /> {t('fertility.log.add')}
          </button>
        }
      >
        {data.days.length === 0 ? (
          <EmptyState icon="health" title={t('fertility.log.empty')} hint={t('fertility.log.emptyHint')} />
        ) : (
          <ul className="list">
            {data.days.slice(0, 12).map((d) => (
              <li key={d.id} className="list__item">
                <Icon name="health" size={18} />
                <button
                  type="button"
                  className="grow stack stack--tight"
                  style={{ background: 'none', border: 0, textAlign: 'left', padding: 0, cursor: 'pointer', color: 'inherit' }}
                  onClick={() => setSheetDate(d.date)}
                >
                  <strong style={{ fontSize: 14 }}>{fmtDate(d.date, 'd MMMM yyyy', locale)}</strong>
                  <span className="card__hint">{dayLine(d, t)}</span>
                </button>
                <button
                  className="btn btn--ghost btn--sm btn--icon"
                  onClick={() => removeFert(d.id, me)}
                >
                  <Icon name="close" size={16} label={t('fertility.delete')} />
                </button>
              </li>
            ))}
          </ul>
        )}
      </Card>

      <Card title={t('fertility.bbt.title')} icon="cycle">
        <div className="stack stack--tight">
          <BbtChart read={bbt} label={t('fertility.bbt.chartLabel', {
            n: bbt.points.length,
            min: bbt.min ?? 0,
            max: bbt.max ?? 0,
          })} />
          <p>{t(bbt.messageKey)}</p>
          {bbt.shiftDate && (
            <p className="card__hint">
              {t('fertility.bbt.shiftOn', { date: fmtDate(bbt.shiftDate, 'd MMM', locale) })}
            </p>
          )}
          {data.days.length > 0 && (
            <div className="table-scroll">
              <table>
                <thead>
                  <tr>
                    <th scope="col">{t('fertility.bbt.table.date')}</th>
                    <th scope="col">{t('fertility.bbt.table.temp')}</th>
                    <th scope="col">{t('fertility.bbt.table.mucus')}</th>
                    <th scope="col">{t('fertility.bbt.table.opk')}</th>
                  </tr>
                </thead>
                <tbody>
                  {data.days.slice(0, 20).map((d) => (
                    <tr key={d.id}>
                      <th scope="row" style={{ textAlign: 'left', fontWeight: 400 }}>
                        {fmtDate(d.date, 'd MMM', locale)}
                      </th>
                      <td>{d.bbtC === undefined ? '—' : `${d.bbtC.toFixed(2)}°`}</td>
                      <td>{d.mucus ? t(`fertility.mucus.${d.mucus}`) : '—'}</td>
                      <td>{d.opk ? t(`fertility.opk.${d.opk}`) : '—'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </Card>

      <Preconception me={me} checks={data.checks} />
      <Questions me={me} questions={data.questions} />

      <DaySheet
        me={me}
        date={sheetDate}
        existing={editing}
        onClose={() => setSheetDate(null)}
      />
    </>
  )
}

function dayLine(d: Of<'fert_day'>, t: (k: MessageKey) => string): string {
  const parts = [
    d.bbtC === undefined ? null : `${d.bbtC.toFixed(2)}°C`,
    d.mucus ? t(`fertility.mucus.${d.mucus}`) : null,
    d.opk ? `OPK ${t(`fertility.opk.${d.opk}`)}` : null,
    d.intercourse ? t('fertility.log.intercourse') : null,
    d.note || null,
  ].filter(Boolean)
  return parts.length ? parts.join(' · ') : t('fertility.log.none')
}

/**
 * Basal temperature line. Hand-rolled SVG rather than a chart library: it is
 * twenty lines, it inherits the theme, and it adds nothing to the bundle.
 * The same numbers appear in the table below, so the line is never the only
 * way to read the data.
 */
function BbtChart({ read, label }: { read: BbtRead; label: string }) {
  if (read.points.length < 2) return null
  const W = 300
  const H = 90
  const lo = read.min! - 0.15
  const hi = read.max! + 0.15
  const span = hi - lo || 1
  const x = (i: number) => (i / (read.points.length - 1)) * W
  const y = (c: number) => H - ((c - lo) / span) * H
  const d = read.points.map((p, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)} ${y(p.celsius).toFixed(1)}`).join(' ')
  const shiftIndex = read.shiftDate ? read.points.findIndex((p) => p.date === read.shiftDate) : -1

  return (
    <svg className="fert-chart" viewBox={`-4 -4 ${W + 8} ${H + 8}`} role="img" aria-label={label}>
      {shiftIndex >= 0 && (
        <line className="fert-chart__shift" x1={x(shiftIndex)} y1={0} x2={x(shiftIndex)} y2={H} />
      )}
      <path className="fert-chart__line" d={d} />
      {read.points.map((p, i) => (
        <circle key={p.date} className="fert-chart__dot" cx={x(i)} cy={y(p.celsius)} r={2.2} />
      ))}
    </svg>
  )
}

/** Exported because "masih menimbang" mode shows this without any TTC tracking. */
export function Preconception({ me, checks }: { me: string; checks: Of<'fert_check'>[] }) {
  const { t } = useI18n()
  const done = (k: PreconceptionItem) => checks.find((c) => c.itemKey === k)

  async function toggle(k: PreconceptionItem) {
    const row = done(k)
    if (row) await patchFert(row.id, { done: !row.done })
    else await addFert(me, { kind: 'fert_check', itemKey: k, done: true })
  }

  const doneCount = PRECONCEPTION_ITEMS.filter((k) => done(k)?.done).length

  return (
    <Card title={t('fertility.pre.title')} icon="check" hint={t('fertility.pre.hint')}>
      <p className="card__hint">
        {t('fertility.pre.done', { n: doneCount, total: PRECONCEPTION_ITEMS.length })}
      </p>
      <div className="fert-signs">
        {PRECONCEPTION_ITEMS.map((k) => (
          <label key={k}>
            <input type="checkbox" checked={!!done(k)?.done} onChange={() => toggle(k)} />
            <span>{t(`fertility.pre.${k}`)}</span>
          </label>
        ))}
      </div>
    </Card>
  )
}

export function Questions({ me, questions }: { me: string; questions: Of<'fert_question'>[] }) {
  const { t } = useI18n()
  const [text, setText] = useState('')

  async function add(value: string) {
    const v = value.trim()
    if (!v) return
    await addFert(me, { kind: 'fert_question', text: v, asked: false })
    setText('')
  }

  return (
    <Card title={t('fertility.q.title')} icon="repair" hint={t('fertility.q.hint')}>
      <div className="stack stack--tight">
        <Field label={t('fertility.q.add')}>
          {(p) => (
            <input
              {...p}
              value={text}
              placeholder={t('fertility.q.placeholder')}
              onChange={(e) => setText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault()
                  add(text)
                }
              }}
            />
          )}
        </Field>
        <button className="btn btn--soft btn--block" onClick={() => add(text)} disabled={!text.trim()}>
          <Icon name="plus" size={16} /> {t('fertility.q.add')}
        </button>

        <p className="card__hint">{t('fertility.q.suggested')}</p>
        <div className="row" style={{ gap: 'var(--space-2)' }}>
          {SUGGESTED_QUESTIONS.map((q) => (
            <button
              key={q}
              type="button"
              className="chip"
              style={{ cursor: 'pointer', minHeight: 34, textAlign: 'left' }}
              onClick={() => add(t(`fertility.q.${q}`))}
            >
              {t(`fertility.q.${q}`)}
            </button>
          ))}
        </div>

        {questions.length === 0 ? (
          <EmptyState icon="info" title={t('fertility.q.empty')} />
        ) : (
          <ul className="list">
            {questions.map((q) => (
              <li key={q.id} className="list__item">
                <input
                  type="checkbox"
                  checked={q.asked}
                  aria-label={t('fertility.q.asked')}
                  onChange={() => patchFert(q.id, { asked: !q.asked })}
                />
                <span className="grow" style={{ fontSize: 14, opacity: q.asked ? 0.6 : 1 }}>
                  {q.text}
                </span>
                <button className="btn btn--ghost btn--sm btn--icon" onClick={() => removeFert(q.id, me)}>
                  <Icon name="close" size={16} label={t('fertility.delete')} />
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </Card>
  )
}

function DaySheet({
  me,
  date,
  existing,
  onClose,
}: {
  me: string
  date: string | null
  existing: Of<'fert_day'> | undefined
  onClose: () => void
}) {
  const { t } = useI18n()
  // Keyed remount: the sheet holds draft state, and reopening it on a different
  // date must not carry the previous day's values over.
  return (
    <Sheet open={date !== null} onClose={onClose} title={t('fertility.log.sheet')}>
      {date !== null && (
        <DayForm key={`${date}:${existing?.id ?? 'new'}`} me={me} date={date} existing={existing} onClose={onClose} />
      )}
    </Sheet>
  )
}

function DayForm({
  me,
  date,
  existing,
  onClose,
}: {
  me: string
  date: string
  existing: Of<'fert_day'> | undefined
  onClose: () => void
}) {
  const { t } = useI18n()
  const [on, setOn] = useState(date)
  const [bbt, setBbt] = useState(existing?.bbtC?.toString() ?? '')
  const [mucus, setMucus] = useState<Mucus | ''>(existing?.mucus ?? '')
  const [opk, setOpk] = useState<Opk | ''>(existing?.opk ?? '')
  const [sex, setSex] = useState(!!existing?.intercourse)
  const [note, setNote] = useState(existing?.note ?? '')

  async function save() {
    const celsius = Number.parseFloat(bbt)
    await saveDay(me, existing, {
      date: on,
      // A basal thermometer reads 35–38 °C. Anything outside that is a typo, and
      // storing it would bend the chart's scale for weeks.
      ...(Number.isFinite(celsius) && celsius >= 35 && celsius <= 38 ? { bbtC: celsius } : {}),
      ...(mucus ? { mucus } : {}),
      ...(opk ? { opk } : {}),
      ...(sex ? { intercourse: true } : {}),
      ...(note.trim() ? { note: note.trim() } : {}),
    })
    onClose()
  }

  return (
    <div className="stack">
      <Field label={t('fertility.log.date')}>
        {(p) => <input {...p} type="date" value={on} onChange={(e) => setOn(e.target.value)} />}
      </Field>
      <Field label={t('fertility.log.bbt')} hint={t('fertility.log.bbtHint')}>
        {(p) => (
          <input
            {...p}
            type="number"
            inputMode="decimal"
            step="0.01"
            min="35"
            max="38"
            value={bbt}
            onChange={(e) => setBbt(e.target.value)}
          />
        )}
      </Field>

      <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
        <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>{t('fertility.log.mucus')}</legend>
        <div className="row" style={{ gap: 'var(--space-2)' }}>
          {MUCUS_TYPES.map((m) => (
            <button
              key={m}
              type="button"
              aria-pressed={mucus === m}
              className={`chip ${mucus === m ? 'chip--primary' : ''}`}
              style={{ cursor: 'pointer', minHeight: 34 }}
              onClick={() => setMucus(mucus === m ? '' : m)}
            >
              {t(`fertility.mucus.${m}`)}
            </button>
          ))}
        </div>
      </fieldset>

      <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
        <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>{t('fertility.log.opk')}</legend>
        <div className="row" style={{ gap: 'var(--space-2)' }}>
          {OPK_RESULTS.map((o) => (
            <button
              key={o}
              type="button"
              aria-pressed={opk === o}
              className={`chip ${opk === o ? 'chip--primary' : ''}`}
              style={{ cursor: 'pointer', minHeight: 34 }}
              onClick={() => setOpk(opk === o ? '' : o)}
            >
              {t(`fertility.opk.${o}`)}
            </button>
          ))}
        </div>
        <span className="field__hint">{t('fertility.log.opkHint')}</span>
      </fieldset>

      <label className="row" style={{ gap: 'var(--space-3)', fontSize: 14, minHeight: 34 }}>
        <input type="checkbox" checked={sex} onChange={(e) => setSex(e.target.checked)} />
        <span>{t('fertility.log.intercourse')}</span>
      </label>

      <Field label={t('fertility.log.note')}>
        {(p) => (
          <textarea
            {...p}
            value={note}
            placeholder={t('fertility.log.notePlaceholder')}
            onChange={(e) => setNote(e.target.value)}
          />
        )}
      </Field>

      <button className="btn btn--block" onClick={save}>
        {t('common.save')}
      </button>
    </div>
  )
}
