import { useMemo } from 'react'
import { db, logAudit, newEnvelope, patch, setVisibility, softDelete } from '@/db/db'
import { useOwned } from '@/db/hooks'
import type { Envelope, FamilyRecord } from '@/types/domain'
import { asMode, DEFAULT_MODE, type Mode as FertMode } from './modes'
import type { MoodItemId, RecoverySignId } from './postpartumCare'
import type { ShareKey, ShareSnapshot } from './summary'
import type {
  AncSlotId,
  DangerSignId,
  KfSlotId,
  Mucus,
  Opk,
  P4kField,
  PreconceptionItem,
  TriageLevel,
} from './fertilityMath'
import type { AncMeasures, DatingBasis } from './pregnancyPlan'
import type { ArtApptType, ArtMethod } from './advancedMath'

/**
 * Persistence for the fertility module.
 *
 * There is no `fertility` table in `db.ts`, and this feature is not allowed to
 * add one, so every record lives in the existing `family` store — which is the
 * store Phase 10 already designated for fertility and pregnancy. Each kind is
 * prefixed `fert_` so the Keluarga screen's `kind` filters skip these rows and
 * this screen skips theirs. `backup.ts` only requires `kind` on a family row,
 * so backup, audit, visibility, and unpair all keep working unchanged.
 *
 * Everything is `C4_health`, whose default visibility is `private`. Nothing
 * here ever widens that — only the owner can, through the privacy screen.
 */

// The mode state machine lives in `modes.ts`; re-exported here so the older
// call sites that imported `Mode` / `MODES` from the store keep working.
export { MODES, type Mode } from './modes'

export type FertilityBody =
  | { kind: 'fert_mode'; mode: FertMode; note?: string }
  | {
      kind: 'fert_day'
      date: string
      bbtC?: number
      mucus?: Mucus
      opk?: Opk
      intercourse?: boolean
      note?: string
    }
  | { kind: 'fert_check'; itemKey: PreconceptionItem; done: boolean }
  | { kind: 'fert_question'; text: string; asked: boolean }
  | {
      kind: 'fert_anc'
      slotId: AncSlotId
      date: string
      withDoctor: boolean
      place?: string
      /** FE7 — what was measured, as the owner typed it off the Buku KIA page. */
      measures?: AncMeasures
      /** FE7 — what was said, in their own words. Never generated by the app. */
      said?: string
    }
  /**
   * FE5 — which assumption the week count runs on. One row per owner: the LMP
   * itself stays on the shared `pregnancy` record, so this only ever holds the
   * scan and the choice between the two.
   */
  | {
      kind: 'fert_dating'
      basis: DatingBasis
      usgDate?: string
      usgWeeks?: number
      usgDays?: number
    }
  | { kind: 'fert_ttd'; date: string }
  /** Birth date, so the postpartum mode has something to count from. */
  | { kind: 'fert_birth'; date: string }
  | { kind: 'fert_kf'; slotId: KfSlotId; date: string }
  | { kind: 'fert_p4k'; field: P4kField; value: string }
  | { kind: 'fert_kick'; date: string; minutes: number; kicks: number }
  | { kind: 'fert_ctx'; startedAt: string; durationSec: number }
  | { kind: 'fert_triage'; date: string; signIds: DangerSignId[]; level: TriageLevel }
  /** FE13 — one weight / blood-pressure reading, all fields optional. */
  | {
      kind: 'fert_vital'
      date: string
      weightKg?: number
      sistol?: number
      diastol?: number
      note?: string
    }
  /**
   * FE14 — one IVF/IUI cycle. One active row at a time, edited in place; a second
   * pregnancy attempt is a new row only after the owner clears this one.
   */
  | {
      kind: 'fert_art'
      method: ArtMethod
      /** The phase id the owner marked, from `ART_PHASES[method]`. */
      phase?: string
      procedureDate?: string
      betaDate?: string
    }
  | { kind: 'fert_art_appt'; date: string; typeId: ArtApptType; done: boolean; note?: string }
  /**
   * FE16 — the opt-in memorial. The row exists only if the owner created it;
   * there is no default and no prompt. It carries no week count and no "how far
   * along" — only what the owner chose to write.
   */
  | { kind: 'fert_memorial'; date?: string; name?: string; words?: string }
  /**
   * FE17 — one postpartum self check-in per date: physical recovery signs and a
   * mood check-in. The logic in `postpartumCare.ts` turns these into a referral
   * surface; the record itself is just the ticked ids, never a score.
   */
  | {
      kind: 'fert_ppcheck'
      date: string
      recovery: RecoverySignId[]
      mood: MoodItemId[]
      note?: string
    }
  /**
   * FE18 — the partner-visible summary. One row per owner. It is the *only*
   * fertility record whose visibility the owner ever widens: when any item is
   * shared it becomes `shared`, and the denormalised `snapshot` is all the
   * partner can read — the private source rows never cross. `note` is the owner's
   * editable text, kept even while the note item is off so toggling loses nothing.
   */
  | { kind: 'fert_share'; share: ShareKey[]; snapshot: ShareSnapshot; note?: string }

export type FertilityRecord = Envelope & FertilityBody
export type Of<K extends FertilityBody['kind']> = Envelope & Extract<FertilityBody, { kind: K }>

/**
 * One `as never` for the whole feature. Dexie types the table against
 * `FamilyRecord`, whose union does not know these kinds; the alternative is
 * editing the shared domain file, which this feature must not do.
 */
export async function addFert(me: string, body: FertilityBody): Promise<void> {
  await db.family.add({ ...newEnvelope(me, 'C4_health'), ...body } as never)
}

export const patchFert = (id: string, changes: Record<string, unknown>) =>
  patch('family', id, changes)

export const removeFert = (id: string, me: string) => softDelete('family', id, me)

export interface FertilityData {
  mode: FertMode
  modeRow: Of<'fert_mode'> | undefined
  days: Of<'fert_day'>[]
  births: Of<'fert_birth'>[]
  kfVisits: Of<'fert_kf'>[]
  checks: Of<'fert_check'>[]
  questions: Of<'fert_question'>[]
  ancVisits: Of<'fert_anc'>[]
  datingRow: Of<'fert_dating'> | undefined
  ttd: Of<'fert_ttd'>[]
  p4k: Of<'fert_p4k'>[]
  kicks: Of<'fert_kick'>[]
  contractions: Of<'fert_ctx'>[]
  triages: Of<'fert_triage'>[]
  vitals: Of<'fert_vital'>[]
  art: Of<'fert_art'> | undefined
  artAppts: Of<'fert_art_appt'>[]
  memorial: Of<'fert_memorial'> | undefined
  ppChecks: Of<'fert_ppcheck'>[]
  /**
   * Every readable share row: the viewer's own (owner side, FE20 control) plus
   * any the partner shared with them (partner side, FE18). Split by ownerProfileId
   * at the call site.
   */
  shares: Of<'fert_share'>[]
  /** Running pregnancies, reused from the existing `pregnancy` family record. */
  pregnancies: Extract<FamilyRecord, { kind: 'pregnancy' }>[]
  loading: boolean
}

/**
 * Single subscription for the whole screen. Reads through `useOwned`, never
 * `db.family.toArray()` — the visibility gate is only worth something if there
 * is no path around it.
 */
export function useFertility(me: string | undefined): FertilityData {
  const rows = useOwned<FertilityRecord>('family', me)

  return useMemo(() => {
    const all = rows ?? []
    const of = <K extends FertilityBody['kind']>(kind: K) =>
      all.filter((r): r is Of<K> => r.kind === kind)

    const modeRow = of('fert_mode')[0]
    return {
      // Mode lives in an envelope row, not `settings`: on a shared phone the
      // settings table is readable by whoever is signed in, and "lagi pulih" is
      // not something to leak across a profile switch.
      //
      // No row means the quiet mode, not "program hamil": nobody gets a fertile
      // window on their first visit because a default said so.
      mode: modeRow ? asMode(modeRow.mode) : DEFAULT_MODE,
      modeRow,
      days: of('fert_day').sort((a, b) => b.date.localeCompare(a.date)),
      births: of('fert_birth').sort((a, b) => b.date.localeCompare(a.date)),
      kfVisits: of('fert_kf'),
      checks: of('fert_check'),
      questions: of('fert_question'),
      ancVisits: of('fert_anc'),
      datingRow: of('fert_dating')[0],
      ttd: of('fert_ttd'),
      p4k: of('fert_p4k'),
      kicks: of('fert_kick').sort((a, b) => a.date.localeCompare(b.date)),
      contractions: of('fert_ctx').sort((a, b) => a.startedAt.localeCompare(b.startedAt)),
      triages: of('fert_triage').sort((a, b) => b.date.localeCompare(a.date)),
      vitals: of('fert_vital').sort((a, b) => b.date.localeCompare(a.date)),
      art: of('fert_art')[0],
      artAppts: of('fert_art_appt').sort((a, b) => a.date.localeCompare(b.date)),
      memorial: of('fert_memorial')[0],
      ppChecks: of('fert_ppcheck').sort((a, b) => b.date.localeCompare(a.date)),
      shares: of('fert_share'),
      pregnancies: (all as unknown as FamilyRecord[]).filter(
        (r): r is Extract<FamilyRecord, { kind: 'pregnancy' }> =>
          r.kind === 'pregnancy' && r.status === 'jalan',
      ),
      loading: rows === undefined,
    }
  }, [rows])
}

/** Upsert a day row: one row per date, so re-logging edits instead of piling up. */
export async function saveDay(
  me: string,
  existing: Of<'fert_day'> | undefined,
  body: Omit<Extract<FertilityBody, { kind: 'fert_day' }>, 'kind'>,
): Promise<void> {
  if (existing) await patchFert(existing.id, { ...body })
  else await addFert(me, { kind: 'fert_day', ...body })
}

/**
 * Switch mode. Records nothing but the fact of a change: the audit summary is
 * deliberately free of the mode name, because "sedang pulih" leaking into a log
 * anyone can list would be a second data leak (CLAUDE.md §audit).
 */
export async function setMode(
  me: string,
  existing: Of<'fert_mode'> | undefined,
  mode: FertMode,
): Promise<void> {
  if (existing) {
    if (existing.mode === mode) return
    await patchFert(existing.id, { mode })
    await logAudit({
      actorProfileId: me,
      action: 'update',
      objectStore: 'family',
      objectId: existing.id,
      summary: 'ganti mode',
    })
  } else {
    await addFert(me, { kind: 'fert_mode', mode })
  }
}

/** One birth date row, edited in place — a second one would be a second baby. */
export async function setBirthDate(
  me: string,
  existing: Of<'fert_birth'> | undefined,
  date: string,
): Promise<void> {
  if (existing) await patchFert(existing.id, { date })
  else await addFert(me, { kind: 'fert_birth', date })
}

/**
 * FE5 — the dating assumption. One row, edited in place; the LMP itself is
 * patched onto the shared `pregnancy` record it already lives on, so there is
 * never a second copy of it to disagree with the first.
 */
export async function saveDating(
  me: string,
  existing: Of<'fert_dating'> | undefined,
  body: Omit<Extract<FertilityBody, { kind: 'fert_dating' }>, 'kind'>,
): Promise<void> {
  if (existing) await patchFert(existing.id, { ...body })
  else await addFert(me, { kind: 'fert_dating', ...body })
}

/**
 * FE7 — one record per ANC contact, upserted so that coming back to fill in the
 * numbers a week later edits the visit instead of logging a seventh one.
 */
export async function saveAncVisit(
  me: string,
  existing: Of<'fert_anc'> | undefined,
  body: Omit<Extract<FertilityBody, { kind: 'fert_anc' }>, 'kind'>,
): Promise<void> {
  if (existing) await patchFert(existing.id, { ...body })
  else await addFert(me, { kind: 'fert_anc', ...body })
}

/** FE8 — a tablet on a date, ignoring a second tap on a date already logged. */
export async function logTtd(
  me: string,
  taken: readonly Of<'fert_ttd'>[],
  date: string,
): Promise<void> {
  if (taken.some((r) => r.date === date)) return
  await addFert(me, { kind: 'fert_ttd', date })
}

/**
 * FE16 — the opt-in memorial, upserted. Deliberately no default row: the record
 * exists only once the owner has chosen to make it. Removing it is a soft delete
 * like everything else, never a hard erase.
 */
export async function saveMemorial(
  me: string,
  existing: Of<'fert_memorial'> | undefined,
  body: Omit<Extract<FertilityBody, { kind: 'fert_memorial' }>, 'kind'>,
): Promise<void> {
  if (existing) await patchFert(existing.id, { ...body })
  else await addFert(me, { kind: 'fert_memorial', ...body })
}

/**
 * FE17 — upsert one postpartum check-in per date, so coming back the same day
 * edits it instead of stacking a second row.
 */
export async function savePpCheck(
  me: string,
  existing: Of<'fert_ppcheck'> | undefined,
  body: Omit<Extract<FertilityBody, { kind: 'fert_ppcheck' }>, 'kind'>,
): Promise<void> {
  if (existing) await patchFert(existing.id, { ...body })
  else await addFert(me, { kind: 'fert_ppcheck', ...body })
}

/**
 * FE18 — write the share row and set its visibility in one place.
 *
 * The record is created private (C4 default) and only ever widened to `shared`
 * when at least one item carries content — and dropped back to `private` the
 * moment it does not. Visibility goes through `setVisibility`, which is the only
 * function allowed to change it and refuses a non-owner, so the audit line and
 * the owner-only guarantee both come for free.
 */
export async function saveShare(
  me: string,
  existing: Of<'fert_share'> | undefined,
  body: Omit<Extract<FertilityBody, { kind: 'fert_share' }>, 'kind'>,
  hasContent: boolean,
): Promise<void> {
  let id = existing?.id
  if (existing) await patchFert(existing.id, { ...body })
  else {
    const env = newEnvelope(me, 'C4_health')
    id = env.id
    await db.family.add({ ...env, kind: 'fert_share', ...body } as never)
  }
  if (!id) return
  const want: Envelope['visibility'] = hasContent ? 'shared' : 'private'
  const current = existing?.visibility ?? 'private'
  if (current !== want) await setVisibility('family', id, me, want)
}

/** Toggle a KF postpartum contact. Logging one is the whole interaction. */
export async function toggleKf(
  me: string,
  existing: Of<'fert_kf'> | undefined,
  slotId: KfSlotId,
  date: string,
): Promise<void> {
  if (existing) await removeFert(existing.id, me)
  else await addFert(me, { kind: 'fert_kf', slotId, date })
}
