import { useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, VisibilityBadge } from '@/components/ui'
import { useSession } from '@/app/session'
import { useI18n, useT } from '@/i18n'
import {
  MODES,
  MODE_ICON,
  capabilities,
  isBare,
  isQuiet,
  transition,
  type Capability,
  type Mode,
} from './modes'
import { addFert, patchFert, setMode, useFertility, type FertilityData } from './store'
import Trying from './Trying'
import Pregnancy from './Pregnancy'
import { Exploring, NotTrying, Postpartum, Preventing } from './ModePanels'
import { Art, Memorial, Vitals } from './Advanced'
import { Disclaimer, DomainSummary, PartnerSummary, ShareControl } from './SummaryView'
import './fertility.css'

/**
 * Program hamil & kehamilan (FAM-01..03, FE1..FE4).
 *
 * Extends the cycle module rather than duplicating it: the fertile window is
 * computed from the same logged period starts, through the same `cycleMath`.
 *
 * The screen is a projection of one value — the mode — through the capability
 * table in `modes.ts`. Nothing below asks "which mode is this?" twice, so
 * "nothing about conception in `tidak` or `pulih`" cannot be forgotten by a card
 * that was added later.
 *
 * Three deliberate absences: no diagnosis, no risk class, and no claim that
 * following any of this produces a pregnancy. Every estimate carries a range
 * and a caveat, and every record is `C4_health` — private until the owner
 * decides otherwise.
 */
export default function Fertility() {
  const t = useT()
  const { profile } = useSession()
  const me = profile?.id
  const data = useFertility(me)

  if (!profile || !me) return null

  const caps = capabilities(data.mode)
  const quiet = isQuiet(data.mode)
  // FE18 partner side: a summary the *other* person shared reaches this viewer
  // through the read gate as a `fert_share` row they do not own. The owner's own
  // share row (ownerProfileId === me) drives ShareControl below, not this.
  const partnerShare = data.shares.find((s) => s.ownerProfileId !== me)

  return (
    <div className="stack">
      {/* The heading itself is conception copy, so quiet modes get a neutral one. */}
      <h1>{quiet ? t('fertility.title.quiet') : t('fertility.title')}</h1>
      <p className="card__hint">{t('fertility.subtitle')}</p>
      {/* FE19 — the medical disclaimer is on every screen, in every mode, with no
          way to dismiss it. */}
      <Disclaimer />

      {/* FE18 — what the partner shared, if anything. Additive: this viewer's own
          screen follows below. */}
      {partnerShare && <PartnerSummary share={partnerShare} />}

      <ModePicker me={me} data={data} />

      {/* FE20 — the owner's at-a-glance status. Kept out of the quiet modes, where
          a reproductive roll-up is the opposite of what the screen is for. */}
      {!quiet && <DomainSummary me={me} data={data} />}

      {caps.cycleEstimate && !caps.conception && <Preventing me={me} />}
      {caps.prep && !caps.conception && <Exploring me={me} data={data} />}
      {caps.conception && <Trying me={me} data={data} />}
      {caps.conception && <Art me={me} data={data} />}
      {caps.pregnancy && <Pregnancy me={me} data={data} />}
      {caps.pregnancy && <Vitals me={me} data={data} />}
      {caps.postpartum && <Postpartum me={me} data={data} />}
      {caps.quietNote && <Recovery me={me} data={data} />}
      {isBare(data.mode) && <NotTrying />}

      {/* FE18 owner side — pick what the partner may see. Not in the quiet modes. */}
      {!quiet && <ShareControl me={me} data={data} />}
    </div>
  )
}

/**
 * The seven-mode switch.
 *
 * Two things make it safe rather than just functional. In a quiet mode the list
 * is collapsed behind one button, because "Program hamil · masa subur, DPO,
 * suhu basal" is exactly the copy someone in `pulih` mode opened this screen to
 * not read. And a switch that hides part of the screen asks once first, stating
 * only what disappears and that nothing is deleted — never why.
 */
function ModePicker({ me, data }: { me: string; data: FertilityData }) {
  const { t } = useI18n()
  const quiet = isQuiet(data.mode)
  // `null` means "follow the mode" — the list is open unless the mode is a quiet
  // one. Initialising a boolean from `quiet` would freeze the closed state from
  // the first render, before the stored mode has loaded.
  const [override, setOverride] = useState<boolean | null>(null)
  const open = override ?? !quiet
  const [pending, setPending] = useState<Mode | null>(null)

  const capList = (caps: Capability[]) => caps.map((c) => t(`fertility.cap.${c}`)).join(', ')
  const step = pending ? transition(data.mode, pending) : null

  async function pick(to: Mode) {
    const next = transition(data.mode, to)
    if (next === null) return
    if (next.confirm) {
      setPending(to)
      return
    }
    await setMode(me, data.modeRow, to)
  }

  async function commit() {
    if (!pending) return
    await setMode(me, data.modeRow, pending)
    setPending(null)
    // Back to following the mode, so a switch into a quiet mode collapses the
    // list again without being asked twice.
    setOverride(null)
  }

  return (
    <Card title={t('fertility.mode')} icon="settings" hint={t('fertility.mode.hint')}>
      {!open ? (
        <button className="btn btn--soft btn--block" onClick={() => setOverride(true)}>
          <Icon name="settings" size={16} /> {t('fertility.mode.change')}
        </button>
      ) : (
        <>
          <div className="choices" role="radiogroup" aria-label={t('fertility.mode')}>
            {MODES.map((m) => (
              <button
                key={m}
                type="button"
                role="radio"
                aria-checked={data.mode === m}
                className="choice"
                onClick={() => pick(m)}
              >
                <Icon name={MODE_ICON[m]} size={24} />
                <span className="stack stack--tight grow">
                  <span className="choice__title">{t(`fertility.mode.${m}`)}</span>
                  <span className="choice__desc">{t(`fertility.mode.${m}.desc`)}</span>
                </span>
                {data.mode === m && <Icon name="check" size={20} />}
              </button>
            ))}
          </div>

          {step && (
            <div className="stack stack--tight" style={{ marginTop: 'var(--space-3)' }}>
              <p>
                {t(step.effectKey, {
                  hides: capList(step.hides),
                  reveals: capList(step.reveals),
                })}
              </p>
              <div className="row" style={{ gap: 'var(--space-2)' }}>
                <button className="btn btn--sm" onClick={commit}>
                  {t('fertility.mode.confirm')}
                </button>
                <button className="btn btn--ghost btn--sm" onClick={() => setPending(null)}>
                  {t('fertility.mode.cancel')}
                </button>
              </div>
            </div>
          )}

          <p className="card__hint" style={{ marginTop: 'var(--space-3)' }}>
            {t('fertility.mode.noJudge')}
          </p>
          {quiet && (
            <button className="btn btn--ghost btn--sm" onClick={() => setOverride(false)}>
              {t('fertility.mode.close')}
            </button>
          )}
        </>
      )}

      <p className="row" style={{ marginTop: 'var(--space-3)', gap: 'var(--space-2)' }}>
        <VisibilityBadge visibility="private" />
        <span className="card__hint grow">{t('fertility.private')}</span>
      </p>
    </Card>
  )
}

/**
 * Pregnancy-loss mode.
 *
 * Nothing is deleted and nothing is asked. Every week counter, due date, and
 * piece of fetal-development imagery is simply not rendered — the switch is a
 * render branch, not a filter someone could forget to apply. The only thing
 * offered is a private note and a way back out whenever they want it.
 */
function Recovery({ me, data }: { me: string; data: FertilityData }) {
  const t = useT()
  const note = data.modeRow?.note ?? ''

  async function saveNote(next: string) {
    if (data.modeRow) await patchFert(data.modeRow.id, { note: next })
    else await addFert(me, { kind: 'fert_mode', mode: 'pulih', note: next })
  }

  return (
    <>
      <Card title={t('fertility.loss.title')} icon="repair">
        <p>{t('fertility.loss.body')}</p>
      </Card>

      <Card title={t('fertility.loss.keep')} icon="private" hint={t('fertility.loss.keepHint')} />

      {/* FE16 — the memorial is opt-in: it renders its own "create" prompt and
          nothing appears until the owner asks. No re-prompt to try again. */}
      <Memorial me={me} data={data} />


      <Card title={t('fertility.loss.note')} icon="memories">
        <Field label={t('fertility.loss.note')} hint={t('fertility.loss.notePlaceholder')}>
          {(p) => (
            <textarea
              {...p}
              defaultValue={note}
              // Saved on blur rather than per keystroke: this is not a field
              // anyone should watch autosaving while they write it.
              onBlur={(e) => saveNote(e.target.value)}
            />
          )}
        </Field>
      </Card>

      <Card title={t('fertility.loss.support')} icon="heart">
        <EmptyState icon="info" title={t('fertility.loss.support')} hint={t('fertility.loss.supportHint')} />
      </Card>

      <p className="card__hint">{t('fertility.loss.back')}</p>
    </>
  )
}
