import type { FertilityKey } from './messages'

/**
 * FE17 — postpartum recovery tracking and a mood check-in that produces a
 * *referral surface*, never a score.
 *
 * The one rule this file exists to keep: it does not add symptoms up into a
 * number. An EPDS-style score is a screening instrument a clinician administers;
 * a self-typed checklist that renders "you scored 14" would be this app pretending
 * to diagnose. So the output is only ever "nothing flagged", "worth mentioning to
 * someone", or — when a self-harm item is ticked — "please reach out now". The
 * count of concerning items is used to pick that surface and is never shown.
 *
 * Same house rules as the rest of the module: message keys instead of copy, no
 * diagnosis, no named provider. The urgent surface deliberately does not carry a
 * hotline number — inventing one is exactly the "referral provider without a
 * source" the blueprint forbids. See the documented gap in `messages.ts`.
 */

// ---------------------------------------------------------------------------
// Physical recovery
// ---------------------------------------------------------------------------

/**
 * Postpartum recovery signs the owner can tick over the days. `seekCare` marks
 * the ones that are the nifas "tanda bahaya" — the same when-to-call logic as the
 * pregnancy triage, kept local so the copy can be nifas-specific.
 */
export const RECOVERY_SIGNS = [
  { id: 'perdarahanBanyak', seekCare: true },
  { id: 'demam', seekCare: true },
  { id: 'nyeriHebat', seekCare: true },
  { id: 'lukaBernanah', seekCare: true },
  { id: 'betisBengkakMerah', seekCare: true },
  { id: 'pusingPingsan', seekCare: true },
  { id: 'asiSusah', seekCare: false },
  { id: 'kurangTidur', seekCare: false },
  { id: 'nyeriRingan', seekCare: false },
] as const

export type RecoverySignId = (typeof RECOVERY_SIGNS)[number]['id']

export interface RecoveryReview {
  /** Any ticked sign is one to get in touch about. Never a diagnosis. */
  seekCare: boolean
  flagged: RecoverySignId[]
  messageKey: FertilityKey
}

const RECOVERY_IDS = new Set<string>(RECOVERY_SIGNS.map((s) => s.id))
const SEEK_CARE_IDS = new Set<string>(RECOVERY_SIGNS.filter((s) => s.seekCare).map((s) => s.id))

/** Which ticked signs are ones to contact a bidan/dokter about. Presence only. */
export function recoveryReview(selected: readonly string[]): RecoveryReview {
  const flagged = RECOVERY_SIGNS.filter((s) => s.seekCare && selected.includes(s.id)).map((s) => s.id)
  const anyLogged = selected.some((id) => RECOVERY_IDS.has(id))
  return {
    seekCare: flagged.length > 0,
    flagged,
    messageKey: flagged.length > 0
      ? 'fertility.pp.recovery.seek'
      : anyLogged
        ? 'fertility.pp.recovery.ok'
        : 'fertility.pp.recovery.none',
  }
}

export const isRecoverySign = (id: string): id is RecoverySignId => RECOVERY_IDS.has(id)
export const recoverySeekCare = (id: string): boolean => SEEK_CARE_IDS.has(id)

// ---------------------------------------------------------------------------
// Mood check-in — referral surface, never a score
// ---------------------------------------------------------------------------

/**
 * Feelings the owner can tick. `concern` marks the ones that, if present, make
 * the check-in surface a gentle "worth telling someone". `urgent` marks the two
 * that escalate straight to "reach out now" no matter what else is ticked — a
 * self-harm thought is not weighed against anything.
 */
export const MOOD_ITEMS = [
  { id: 'baik', concern: false },
  { id: 'lelah', concern: false },
  { id: 'sedihTerus', concern: true },
  { id: 'cemasBerlebih', concern: true },
  { id: 'nangisTanpaSebab', concern: true },
  { id: 'kosong', concern: true },
  { id: 'susahDekatBayi', concern: true },
  { id: 'nafsuMakanHilang', concern: true },
  { id: 'putusAsa', concern: true, urgent: true },
  { id: 'pikiranMenyakitiDiri', concern: true, urgent: true },
] as const

export type MoodItemId = (typeof MOOD_ITEMS)[number]['id']

/** none → nothing to raise; gentle → worth mentioning; urgent → reach out now. */
export type MoodSurface = 'none' | 'gentle' | 'urgent'

export interface MoodReferral {
  surface: MoodSurface
  /** The line the person reads. The concern count that chose it is never shown. */
  messageKey: FertilityKey
  /** What to do — a referral, never a diagnosis and never a named clinic. */
  actionKey: FertilityKey
}

const MOOD_IDS = new Set<string>(MOOD_ITEMS.map((m) => m.id))
const URGENT_IDS = new Set<string>(MOOD_ITEMS.filter((m) => 'urgent' in m && m.urgent).map((m) => m.id))

/**
 * Presence, not sum. Urgent wins over everything; otherwise any concern item is
 * gentle; otherwise none. There is no threshold count in the output.
 */
export function moodReferral(selected: readonly string[]): MoodReferral {
  const urgent = selected.some((id) => URGENT_IDS.has(id))
  const concern = MOOD_ITEMS.some((m) => m.concern && selected.includes(m.id))

  if (urgent) {
    return {
      surface: 'urgent',
      messageKey: 'fertility.pp.mood.urgent',
      actionKey: 'fertility.pp.mood.urgentAction',
    }
  }
  if (concern) {
    return {
      surface: 'gentle',
      messageKey: 'fertility.pp.mood.gentle',
      actionKey: 'fertility.pp.mood.gentleAction',
    }
  }
  return {
    surface: 'none',
    messageKey: 'fertility.pp.mood.none',
    actionKey: 'fertility.pp.mood.noneAction',
  }
}

export const isMoodItem = (id: string): id is MoodItemId => MOOD_IDS.has(id)
