import type { IconName } from '@/design-system/Icon'
import type { FertilityKey } from './messages'

/**
 * The seven modes, as an explicit state machine (FE1/FE2).
 *
 * Two rules shape everything here:
 *
 * 1. **Every transition is allowed, in both directions.** A person who switches
 *    to "lagi pulih" after a loss must be able to leave again months later
 *    without the app asking why, and someone who moves from "cegah" straight to
 *    "hamil" is not skipping a step they owe us. So the graph is total: the only
 *    edge that does not exist is a mode to itself. Nothing about a switch is
 *    ranked, scored, or explained back to the user as a decision.
 * 2. **A mode is a capability set, not a label.** What the screen shows is
 *    derived from `CAPS` alone, so "nothing about conception in `tidak` or
 *    `pulih`" is one table entry rather than a condition every card has to
 *    remember. `modeUi.test.tsx` renders the screen in those modes and asserts
 *    the conception copy is absent.
 *
 * Mode ids are Indonesian and are also stored values — `program`, `hamil`, and
 * `pulih` predate the other four and must keep their spelling, because rows
 * written before this file exist in people's browsers.
 */
export const MODES = [
  'tidak', // not trying — the screen stays quiet
  'cegah', // preventing — period outlook only, never presented as contraception
  'jelajah', // exploring — readiness talk, no tracking
  'program', // trying — fertile window, DPO, BBT / mucus / OPK
  'hamil', // pregnant
  'nifas', // postpartum
  'pulih', // after a pregnancy loss
] as const
export type Mode = (typeof MODES)[number]

export const DEFAULT_MODE: Mode = 'tidak'

export const CAPABILITIES = [
  /** Next-period estimate, always as a range with a confidence. */
  'cycleEstimate',
  /** Pre-conception checklist and questions to bring to a bidan or dokter. */
  'prep',
  /** Fertile window, DPO, and the TTC inputs (BBT, lendir, OPK). */
  'conception',
  /** Week counter, ANC, TTD, P4K, kick counts, contractions. */
  'pregnancy',
  /** Days since birth and the KF visit windows. */
  'postpartum',
  /** A private note and nothing else. */
  'quietNote',
] as const
export type Capability = (typeof CAPABILITIES)[number]

const CAPS: Record<Mode, readonly Capability[]> = {
  tidak: [],
  cegah: ['cycleEstimate'],
  jelajah: ['prep'],
  program: ['cycleEstimate', 'prep', 'conception'],
  hamil: ['pregnancy'],
  nifas: ['postpartum'],
  pulih: ['quietNote'],
}

export type CapabilitySet = Record<Capability, boolean>

/** What this mode is allowed to render. The only source the screens read. */
export function capabilities(mode: Mode): CapabilitySet {
  const on = CAPS[mode]
  return Object.fromEntries(CAPABILITIES.map((c) => [c, on.includes(c)])) as CapabilitySet
}

export const can = (mode: Mode, cap: Capability): boolean => CAPS[mode].includes(cap)

/**
 * Modes where the whole screen must be free of conception content — including
 * the words in the mode picker, which is why the picker collapses behind a
 * disclosure here instead of listing "Program hamil" next to a fresh loss.
 */
export const QUIET_MODES: readonly Mode[] = ['tidak', 'pulih']
export const isQuiet = (mode: Mode): boolean => QUIET_MODES.includes(mode)

/** No capability at all: the screen has nothing to render but a mode switch. */
export const isBare = (mode: Mode): boolean => CAPS[mode].length === 0

/** Cast from a stored value. Unknown or missing ids fall back to the quiet mode. */
export const asMode = (value: unknown): Mode =>
  MODES.includes(value as Mode) ? (value as Mode) : DEFAULT_MODE

export const MODE_ICON: Record<Mode, IconName> = {
  tidak: 'private',
  cegah: 'shield',
  jelajah: 'info',
  program: 'cycle',
  hamil: 'pregnancy',
  nifas: 'baby',
  pulih: 'repair',
}

export interface Transition {
  from: Mode
  to: Mode
  /** Capabilities the screen loses. Hidden, never deleted. */
  hides: Capability[]
  /** Capabilities the screen gains. */
  reveals: Capability[]
  /**
   * Ask once before switching — only because a whole area of the screen
   * disappears, and only ever stating what changes. The prompt has no opinion
   * about the direction and no "are you sure?" about the person's life.
   */
  confirm: boolean
  /** What changes, as a message key. */
  effectKey: FertilityKey
  /** Structural: a mode switch never removes a record. */
  readonly deletes: false
}

/**
 * The edge between two modes, or `null` for a mode to itself. Total by design —
 * see rule 1 above. Callers use `hides` / `reveals` to tell the user what will
 * change before it changes.
 */
export function transition(from: Mode, to: Mode): Transition | null {
  if (from === to) return null
  const before = CAPS[from]
  const after = CAPS[to]
  const hides = before.filter((c) => !after.includes(c))
  const reveals = after.filter((c) => !before.includes(c))

  return {
    from,
    to,
    hides,
    reveals,
    confirm: hides.length > 0,
    effectKey:
      hides.length && reveals.length
        ? 'fertility.mode.effect.changes'
        : hides.length
          ? 'fertility.mode.effect.hides'
          : reveals.length
            ? 'fertility.mode.effect.reveals'
            : 'fertility.mode.effect.same',
    deletes: false,
  }
}
